(function(g){g.__QURAN_DATA=g.__QURAN_DATA||{};g.__QURAN_DATA["tamil-052"]={"sura":52,"name_ar":"الطور","name_en":"At-Tur","verses":49,"source":"https://www.tamililquran.com/tafsiribnkathir.php","count":49,"missing":[],"data":{"1":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=52&ayah=16\" class=\"link\">52:16</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 52:16 ஐ பார்க்கவும்"},"2":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=52&ayah=16\" class=\"link\">52:16</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 52:16 ஐ பார்க்கவும்"},"3":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=52&ayah=16\" class=\"link\">52:16</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 52:16 ஐ பார்க்கவும்"},"4":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=52&ayah=16\" class=\"link\">52:16</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 52:16 ஐ பார்க்கவும்"},"5":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=52&ayah=16\" class=\"link\">52:16</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 52:16 ஐ பார்க்கவும்"},"6":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=52&ayah=16\" class=\"link\">52:16</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 52:16 ஐ பார்க்கவும்"},"7":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=52&ayah=16\" class=\"link\">52:16</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 52:16 ஐ பார்க்கவும்"},"8":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=52&ayah=16\" class=\"link\">52:16</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 52:16 ஐ பார்க்கவும்"},"9":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=52&ayah=16\" class=\"link\">52:16</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 52:16 ஐ பார்க்கவும்"},"10":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=52&ayah=16\" class=\"link\">52:16</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 52:16 ஐ பார்க்கவும்"},"11":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=52&ayah=16\" class=\"link\">52:16</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 52:16 ஐ பார்க்கவும்"},"12":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=52&ayah=16\" class=\"link\">52:16</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 52:16 ஐ பார்க்கவும்"},"13":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=52&ayah=16\" class=\"link\">52:16</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 52:16 ஐ பார்க்கவும்"},"14":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=52&ayah=16\" class=\"link\">52:16</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 52:16 ஐ பார்க்கவும்"},"15":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=52&ayah=16\" class=\"link\">52:16</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 52:16 ஐ பார்க்கவும்"},"16":{"html":"<strong>இது மக்காவில் அருளப்பட்டது</strong><br />\r\n<br />\r\n<strong>ஸூரத்துத் தூர் அத்தியாயத்தின் சிறப்புகள்</strong><br />\r\n<br />\r\nநபி (ஸல்) அவர்கள் மக்ரிப் தொழுகையில் ஸூரத்துத் தூர் ஓதுவதை நான் கேட்டேன். நிச்சயமாக, அவர்களை விட அழகான ஒரு குரலையோ அல்லது ஓதலையோ நான் ஒருபோதும் கேட்டதே இல்லை என்று ஜுபைர் இப்னு முத்இம் (ரழி) அவர்கள் கூறியதாக மாலிக் அறிவிக்கிறார். இந்த ஹதீஸ் மாலிக் வழியாக வரும் அறிவிப்பாளர் தொடரைக் கொண்டு இரண்டு ஸஹீஹ்களிலும் (புகாரி மற்றும் முஸ்லிம்) பதிவு செய்யப்பட்டுள்ளது. உம்மு ஸலமா (ரழி) அவர்கள் கூறியதாவது: \"நான் நோய்வாய்ப்பட்டிருப்பதாக அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் முறையிட்டேன். அதற்கு அவர்கள்,<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">طُوفِي</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">وَرَاءِ</span> <span class=\"quran-arabic-font text-success\">النَّاسِ</span> <span class=\"quran-arabic-font text-success\">وَأَنْتِ</span> <span class=\"quran-arabic-font text-success\">رَاكِبَة</span>»<br />\r\n<br />\r\n(நீ வாகனத்தில் அமர்ந்தவாறே மக்களுக்குப் பின்னால் தவாஃப் செய்வாயாக) என்று கூறினார்கள். அவ்வாறே அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கஅபாவிற்கு அருகில் தொழுது கொண்டு ஸூரத்துத் தூர் ஓதிக் கொண்டிருந்தபோது நான் தவாஃப் செய்தேன்.\" இது புகாரியில் பதிவாகியுள்ளது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بِسْمِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَـنِ</span> <span class=\"quran-arabic-font text-success\">الرَّحِيمِ</span><br />\r\n<br />\r\nஅளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.<br />\r\n<br />\r\n<strong>வேதனை வருவது உறுதி என அல்லாஹ் சத்தியம் செய்தல்</strong><br />\r\n<br />\r\nஅல்லாஹ் தன் படைப்புகளின் மீது சத்தியம் செய்கிறான். இது அவனது மாபெரும் ஆற்றலுக்கு ஒரு சான்றாகும். அவனது வேதனை நிச்சயமாக அவனது எதிரிகளை வந்தடையும்; அதிலிருந்து தப்பிக்க அவர்களுக்கு எந்த வழியும் இருக்காது. 'அத்-தூர்' என்பது மரங்கள் நிறைந்த மலையாகும். மூஸா (அலை) அவர்களிடம் அல்லாஹ் பேசிய மலையும், ஈஸா (அலை) அவர்களின் நபித்துவத்தை அல்லாஹ் தொடங்கிய மலையும் இது போன்றதே ஆகும். மரங்கள் இல்லாத மலை 'ஜபல்' என்று அழைக்கப்படும், 'தூர்' என்று அல்ல. அல்லாஹ் கூறினான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَكِتَـبٍ</span> <span class=\"quran-arabic-font text-success\">مُّسْطُورٍ</span><br />\r\n<br />\r\n(எழுதப்பட்ட வேதத்தின் மீதும் சத்தியமாக), இது 'அல்-லவ்ஹுல் மஹ்ஃபூழ்' (பாதுகாக்கப்பட்ட ஏடு) என்று கூறப்படுகிறது. மக்கள் ஓதும் வஹீ (இறைச்செய்தி) அருளப்பட்ட வேதங்களையும் இது குறிப்பதாகக் கூறப்படுகிறது. இதனால்தான் அல்லாஹ் கூறினான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">رَقٍّ</span> <span class=\"quran-arabic-font text-success\">مَّنْشُورٍ</span> - <span class=\"quran-arabic-font text-success\">وَالْبَيْتِ</span> <span class=\"quran-arabic-font text-success\">الْمَعْمُورِ</span><br />\r\n<br />\r\n(விரிக்கப்பட்ட மெல்லிய தோலில் எழுதப்பட்ட வேதத்தின் மீதும், 'அல்-பைத் அல்-மஃமூர்' மீதும் சத்தியமாக.) இரண்டு ஸஹீஹ்களிலும், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் விண்வெளிப் பயணம் (இஸ்ரா) குறித்த ஹதீஸில், ஏழாவது வானத்திற்கு ஏறிச் சென்ற பிறகு இவ்வாறு கூறியுள்ளார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">رُفِعَ</span> <span class=\"quran-arabic-font text-success\">بِي</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">الْبَيْتِ</span> <span class=\"quran-arabic-font text-success\">الْمَعْمُورِ،</span> <span class=\"quran-arabic-font text-success\">وَإِذَا</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">يَدْخُلُهُ</span> <span class=\"quran-arabic-font text-success\">كُلَّ</span> <span class=\"quran-arabic-font text-success\">يَوْمٍ</span> <span class=\"quran-arabic-font text-success\">سَبْعُونَ</span> <span class=\"quran-arabic-font text-success\">أَلْفًا،</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يَعُودُونَ</span> <span class=\"quran-arabic-font text-success\">إِلَيْهِ</span> <span class=\"quran-arabic-font text-success\">آخِرَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِم</span>»<br />\r\n<br />\r\n(பின்னர் நான் 'அல்-பைத் அல்-மஃமூர்'க்கு அழைத்துச் செல்லப்பட்டேன். அங்கு ஒவ்வொரு நாளும் எழுபதாயிரம் வானவர்கள் நுழைகிறார்கள். அவர்கள் அங்கிருந்து வெளியேறினால் மீண்டும் ஒருபோதும் திரும்புவதில்லை.) பூமியில் உள்ள மக்கள் கஅபாவை தவாஃப் செய்வதைப் போல வானவர்கள் 'அல்-பைத் அல்-மஃமூர்'இல் அல்லாஹ்வை வணங்கி, தவாஃப் செய்கிறார்கள். 'அல்-பைத் அல்-மஃமூர்' என்பது ஏழாவது வானத்தில் உள்ளவர்களின் கஅபா ஆகும். இஸ்ரா பயணத்தின் போது இப்ராஹீம் அல்-கலீல் (அலை) அவர்கள் 'அல்-பைத் அல்-மஃமூர்'இல் முதுகு சாய்ந்து அமர்ந்திருப்பதை நபி (ஸல்) அவர்கள் கண்டார்கள். பூமியில் கஅபாவை இப்ராஹீம் (அலை) அவர்களே கட்டினார்கள். எனவே, செயலுக்கேற்ற கூலி வழங்கப்படுகிறது. 'அல்-பைத் அல்-மஃமூர்' கஅபாவிற்கு நேர் மேலாக அமைந்துள்ளது. ஒவ்வொரு வானத்திற்கும் அதற்கென ஒரு வழிபாட்டுத் தலம் உண்டு; அதுவே அங்கு வசிப்பவர்களின் கிப்லா (தொழுகை திசை) ஆகும். கீழ் வானத்தில் உள்ள இல்லம் 'பைத் அல்-இஸ்ஸா' என்று அழைக்கப்படுகிறது. அல்லாஹ்வே மிக அறிந்தவன்.<br />\r\n<br />\r\nஉயர்ந்தோன் அல்லாஹ்வின் கூற்று,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالسَّقْفِ</span> <span class=\"quran-arabic-font text-success\">الْمَرْفُوعِ</span><br />\r\n<br />\r\n(உயர்த்தப்பட்ட முகட்டின் மீதும் சத்தியமாக.) அலீ இப்னு அபீ தாலிப் (ரழி) அவர்கள் இதற்கு \"வானம்\" என்று விளக்கமளித்ததாக ஸுஃப்யான் அத்-தவ்ரி, ஷுஃபா மற்றும் அபூ அல்-அஹ்வஸ் ஆகியோர் ஸிமாக் மற்றும் காலித் இப்னு அர்அரா வழியாக அறிவிக்கின்றனர்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالسَّقْفِ</span> <span class=\"quran-arabic-font text-success\">الْمَرْفُوعِ</span><br />\r\n<br />\r\n(உயர்த்தப்பட்ட முகட்டின் மீதும் சத்தியமாக) என்பதற்குப் பிறகு அலீ (ரழி) அவர்கள் பின்வரும் வசனத்தை ஓதினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَجَعَلْنَا</span> <span class=\"quran-arabic-font text-success\">السَّمَآءَ</span> <span class=\"quran-arabic-font text-success\">سَقْفاً</span> <span class=\"quran-arabic-font text-success\">مَّحْفُوظاً</span> <span class=\"quran-arabic-font text-success\">وَهُمْ</span> <span class=\"quran-arabic-font text-success\">عَنْ</span> <span class=\"quran-arabic-font text-success\">ءَايَـتِهَا</span> <span class=\"quran-arabic-font text-success\">مُعْرِضُونَ</span><br />\r\n<br />\r\n(மேலும் நாம் வானத்தைப் பாதுகாக்கப்பட்ட முகடாக ஆக்கினோம். அவர்களோ அதிலுள்ள அத்தாட்சிகளைப் புறக்கணிக்கிறார்கள்.) (<a href=\"qurandisp.php?sura=21&ayah=32\" class=\"link\">21:32</a>). இதே போன்ற கருத்தையே முஜாஹித், கதாதா, அஸ்-ஸுத்தீ, இப்னு ஜுரைஜ், இப்னு ஸைத் ஆகியோரும் கூறியுள்ளனர். இப்னு ஜரீர் அவர்களும் இதனையே விரும்பத்தக்க கருத்தாகக் கொண்டுள்ளார்.<br />\r\n<br />\r\nஉயர்ந்தோன் அல்லாஹ்வின் கூற்று,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالْبَحْرِ</span> <span class=\"quran-arabic-font text-success\">الْمَسْجُورِ</span><br />\r\n<br />\r\n('மஸ்ஜூர்' ஆன கடலின் மீதும் சத்தியமாக.) இது பூமியில் உள்ள கடல்களைக் குறிப்பதாகப் பெரும்பான்மையோர் கூறுகின்றனர். 'மஸ்ஜூர்' என்றால், மறுமை நாளில் கடல் நெருப்பால் மூட்டப்படும் என்று பொருள். அல்லாஹ் மற்றொரு வசனத்தில் கூறுவது போல்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِذَا</span> <span class=\"quran-arabic-font text-success\">الْبِحَارُ</span> <span class=\"quran-arabic-font text-success\">سُجِّرَتْ</span><br />\r\n<br />\r\n(கடல்கள் தீமூட்டப்படும் போது.) (<a href=\"qurandisp.php?sura=81&ayah=6\" class=\"link\">81:6</a>) அதாவது, அது நெருப்பால் எரிக்கப்பட்டு, ஒன்றுதிரட்டப்படும் மைதானத்தில் உள்ள மக்களைச் சூழ்ந்து கொள்ளும் கொழுந்துவிட்டு எரியும் நெருப்பாக மாறும். அலீ இப்னு அபீ தாலிப் (ரழி) அவர்களிடமிருந்து ஸயீத் இப்னுல் முஸய்யிப் இதனை அறிவித்துள்ளார். இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்தும் இது அறிவிக்கப்பட்டுள்ளது. மேலும் ஸயீத் இப்னு ஜுபைர், முஜாஹித், அப்துல்லாஹ் இப்னு உபைத் இப்னு உமைர் போன்றோரின் கருத்தும் இதுவேயாகும். கதாதா கூறுகையில், \"'மஸ்ஜூர்' என்பது 'நிரப்பப்பட்ட கடல்' ஆகும்.\" இப்னு ஜரீர் இந்த விளக்கத்தையே முன்மொழிகிறார்; ஏனெனில் கடல் இப்போது நெருப்பால் எரிக்கப்படவில்லை, மாறாக அது நிரம்பியுள்ளது என்று அவர் கூறுகிறார்.<br />\r\n<br />\r\nஅல்லாஹ்வின் கூற்று;<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">عَذَابَ</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ</span> <span class=\"quran-arabic-font text-success\">لَوَاقِعٌ</span><br />\r\n<br />\r\n(நிச்சயமாக உமது இறைவனின் வேதனை நிகழ்ந்தே தீரும்.) இது சத்தியத்தின் பதிலாகும். அவனது வேதனை நிச்சயமாக நிராகரிப்பாளர்களைத் தாக்கும் என்பதை இது உணர்த்துகிறது. அல்லாஹ் மற்றோர் இடத்தில் கூறுவது போல்;<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">دَافِعٍ</span><br />\r\n<br />\r\n(அதைத் தடுப்பவர் எவருமில்லை.) அல்லாஹ் அவர்களுக்கு வேதனையை அளிக்க முடிவு செய்துவிட்டால், அதை யாராலும் தடுக்க முடியாது. அல்-ஹாஃபிழ் அபூ பக்ர் இப்னு அபி அத்-துன்யா அவர்கள் ஜஃபர் இப்னு ஸைத் அல்-அப்தீ வாயிலாகப் பதிவு செய்துள்ளார்கள்: \"ஒருமுறை இரவு வேளையில் உமர் (ரழி) அவர்கள் மதீனாவில் மக்களின் நலனை அறியச் சென்றபோது, ஒரு மனிதர் தன் வீட்டில் உபரியான தொழுகையில் (தஹஜ்ஜுத்) ஈடுபட்டு ஓதிக் கொண்டிருப்பதைச் செவியுற்றார்கள். உமர் (ரழி) அமைதியாக நின்று அவர் ஓதுவதைக் கேட்டார்கள். அவர்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالطُّورِ</span><br />\r\n<br />\r\n(தூர் மலை மீது சத்தியமாக) என்று தொடங்கி, பின்வரும் வசனத்தை எட்டியபோது,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">عَذَابَ</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ</span> <span class=\"quran-arabic-font text-success\">لَوَاقِعٌ</span> - <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">دَافِعٍ</span><br />\r\n<br />\r\n(நிச்சயமாக உமது இறைவனின் வேதனை நிகழ்ந்தே தீரும். அதைத் தடுப்பவர் எவருமில்லை.) 'கஅபாவின் இறைவன் மீது ஆணையாக! இது உண்மையான சத்தியம்' என்று உமர் (ரழி) கூறினார்கள். பின்னர் தம் கழுதையிலிருந்து இறங்கி ஒரு சுவரின் ஓரத்தில் சிறிது நேரம் அமர்ந்தார்கள். வீடு திரும்பிய அவர்கள் ஒரு மாத காலம் நோய்வாய்ப்பட்டார்கள். மக்கள் அவர்களை நலம் விசாரிக்க வந்தனர், ஆனால் அவர்களுக்கு என்ன நேர்ந்தது என்பது யாருக்கும் தெரிந்திருக்கவில்லை.\" அல்லாஹ் உமர் (ரழி) அவர்களைப் பொருந்திக் கொள்வானாக.<br />\r\n<br />\r\n<strong>வேதனை நாள் மற்றும் மறுமை நாள் பற்றிய விளக்கம்</strong><br />\r\n<br />\r\nஅல்லாஹ் கூறினான்;<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">تَمُورُ</span> <span class=\"quran-arabic-font text-success\">السَّمَآءُ</span> <span class=\"quran-arabic-font text-success\">مَوْراً</span><br />\r\n<br />\r\n(வானம் கடுமையாக அசையும் நாளில்.) இப்னு அப்பாஸ் (ரழி) மற்றும் கதாதா ஆகியோர் \"கடுமையாக நடுங்குதல்\" என்று கூறினர். இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து \"பிளந்துவிடுதல்\" என்றும் அறிவிக்கப்பட்டுள்ளது. முஜாஹித் \"வேகமாகச் சுழலும்\" என்றார். அத்-தஹ்ஹாக் கூறுகையில், \"அல்லாஹ்வின் கட்டளையால் வானம் வேகமாகச் சுழன்று நகரும், அதன் பகுதிகள் ஒன்றோடொன்று மோதி நகரும்\" என்றார். 'மவ்ரா' என்ற சொல்லுக்குச் சுழலுதல் மற்றும் நடுங்குதல் என்ற பொருள் இருப்பதால் இப்னு ஜரீர் இதனையே சிறந்த கருத்தாகக் கொள்கிறார். அல்லாஹ் கூறினான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَتَسِيرُ</span> <span class=\"quran-arabic-font text-success\">الْجِبَالُ</span> <span class=\"quran-arabic-font text-success\">سَيْراً</span><br />\r\n<br />\r\n(மேலும் மலைகள் நகர்ந்து செல்லும்.) அவை மறைந்து, காற்றால் அடித்துச் செல்லப்படும் துகள்களாக மாறும்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَوَيْلٌ</span> <span class=\"quran-arabic-font text-success\">يَوْمَئِذٍ</span> <span class=\"quran-arabic-font text-success\">لِّلْمُكَذِّبِينَ</span><br />\r\n<br />\r\n(அந்நாளில் பொய்யாக்குபவர்களுக்குக் கேடுதான்.) அல்லாஹ் அவர்கள் மீது இறக்கும் வேதனை மற்றும் தண்டனையினால் அன்றைய தினம் அவர்களுக்கு அழிவு ஏற்படும்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">هُمْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">خَوْضٍ</span> <span class=\"quran-arabic-font text-success\">يَلْعَبُونَ</span><br />\r\n<br />\r\n(அவர்கள் வீணானவற்றில் மூழ்கி விளையாடிக் கொண்டிருக்கிறார்கள்.) அதாவது அவர்கள் இவ்வுலகில் வீண் காரியங்களில் ஈடுபட்டு, மார்க்கத்தைப் பரிகாசப் பொருளாக ஆக்குகிறார்கள்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">يُدَعُّونَ</span><br />\r\n<br />\r\n(அவர்கள் பலவந்தமாகத் தள்ளப்படும் நாளில்.) அதாவது அவர்கள் வன்முறையாக இழுத்துச் செல்லப்படுவார்கள்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">نَارِ</span> <span class=\"quran-arabic-font text-success\">جَهَنَّمَ</span> <span class=\"quran-arabic-font text-success\">دَعًّا</span><br />\r\n<br />\r\n(நரக நெருப்பை நோக்கி கொடூரமாகவும் பலவந்தமாகவும் தள்ளப்படுவார்கள்.) முஜாஹித், அஷ்-ஷஃபீ, முஹம்மத் இப்னு கஅப், அத்-தஹ்ஹாக், அஸ்-ஸுத்தீ மற்றும் அத்-தவ்ரி ஆகியோர் \"அவர்கள் கடுமையாக நெருப்பிற்குள் தள்ளப்படுவார்கள்\" என்று கூறுகின்றனர். அல்லாஹ் கூறினான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">هَـذِهِ</span> <span class=\"quran-arabic-font text-success\">النَّارُ</span> <span class=\"quran-arabic-font text-success\">الَّتِى</span> <span class=\"quran-arabic-font text-success\">كُنتُم</span> <span class=\"quran-arabic-font text-success\">بِهَا</span> <span class=\"quran-arabic-font text-success\">تُكَذِّبُونَ</span><br />\r\n<br />\r\n(நீங்கள் எதை மறுத்துக் கொண்டிருந்தீர்களோ, அந்த நரகம் இதுதான்.) அதாவது தண்டனைக்குரிய வானவர்கள் அவர்களைக் கண்டிக்கும் விதமாக இவ்வாறு கூறுவார்கள்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَفَسِحْرٌ</span> <span class=\"quran-arabic-font text-success\">هَـذَا</span> <span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">أَنتُمْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تُبْصِرُونَ</span><br />\r\n<br />\r\n(இது சூனியமா? அல்லது நீங்கள் பார்க்கவில்லையா?)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">اصْلَوْهَا</span><br />\r\n<br />\r\n(இதில் நுழைந்து கருகிவிடுங்கள்.) அதாவது 'எல்லா திசைகளிலிருந்தும் உங்களைச் சூழ்ந்து கொள்ளும் இந்த நெருப்பில் நுழையுங்கள்' என்று பொருள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَاصْبِرُواْ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تَصْبِرُواْ</span> <span class=\"quran-arabic-font text-success\">سَوَآءٌ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُمْ</span><br />\r\n<br />\r\n(நீங்கள் பொறுமையாக இருந்தாலும் அல்லது பொறுமையிழந்து காணப்பட்டாலும் உங்களுக்கு சமமே.) 'இதன் வேதனையை நீங்கள் சகித்துக் கொண்டாலும் இல்லாவிட்டாலும், அதிலிருந்து நீங்கள் ஒருபோதும் தப்பிக்க முடியாது.'<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّمَا</span> <span class=\"quran-arabic-font text-success\">تُجْزَوْنَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">كُنتُمْ</span> <span class=\"quran-arabic-font text-success\">تَعْمَلُونَ</span><br />\r\n<br />\r\n(நீங்கள் செய்து கொண்டிருந்தவற்றுக்கே நீங்கள் கூலி கொடுக்கப்படுகிறீர்கள்.) நிச்சயமாக அல்லாஹ் யாருக்கும் அநீதி இழைப்பதில்லை. ஒவ்வொருவருக்கும் அவரவர் செயல்களுக்கு ஏற்பவே அல்லாஹ் கூலி வழங்குகிறான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الْمُتَّقِينَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">جَنَّـتٍ</span> <span class=\"quran-arabic-font text-success\">وَنَعِيمٍ</span> - <span class=\"quran-arabic-font text-success\">فَـكِهِينَ</span> <span class=\"quran-arabic-font text-success\">بِمَآ</span> <span class=\"quran-arabic-font text-success\">ءَاتَـهُمْ</span> <span class=\"quran-arabic-font text-success\">رَبُّهُمْ</span> <span class=\"quran-arabic-font text-success\">وَوَقَـهُمْ</span> <span class=\"quran-arabic-font text-success\">رَبُّهُمْ</span> <span class=\"quran-arabic-font text-success\">عَذَابَ</span> <span class=\"quran-arabic-font text-success\">الْجَحِيمِ</span><br />\r\n<br />\r\n(நிச்சயமாக இறையச்சம் உடையவர்கள், சுவர்க்கச் சோலைகளிலும், (அவற்றின்) இன்பத்திலும் இருப்பார்கள். தங்கள் இறைவன் தங்களுக்கு அளித்ததைக் கொண்டு அவர்கள் மகிழ்ந்திருப்பார்கள்; மேலும் அவர்களுடைய இறைவன் நரக வேதனையிலிருந்து அவர்களைக் காப்பாற்றி விட்டான்.)<br />\r\n<br />","text":"இது மக்காவில் அருளப்பட்டது\n\r\n\n\r\nஸூரத்துத் தூர் அத்தியாயத்தின் சிறப்புகள்\n\r\n\n\r\nநபி (ஸல்) அவர்கள் மக்ரிப் தொழுகையில் ஸூரத்துத் தூர் ஓதுவதை நான் கேட்டேன். நிச்சயமாக, அவர்களை விட அழகான ஒரு குரலையோ அல்லது ஓதலையோ நான் ஒருபோதும் கேட்டதே இல்லை என்று ஜுபைர் இப்னு முத்இம் (ரழி) அவர்கள் கூறியதாக மாலிக் அறிவிக்கிறார். இந்த ஹதீஸ் மாலிக் வழியாக வரும் அறிவிப்பாளர் தொடரைக் கொண்டு இரண்டு ஸஹீஹ்களிலும் (புகாரி மற்றும் முஸ்லிம்) பதிவு செய்யப்பட்டுள்ளது. உம்மு ஸலமா (ரழி) அவர்கள் கூறியதாவது: \"நான் நோய்வாய்ப்பட்டிருப்பதாக அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் முறையிட்டேன். அதற்கு அவர்கள்,\n\r\n\n\r\n«طُوفِي مِنْ وَرَاءِ النَّاسِ وَأَنْتِ رَاكِبَة»\n\r\n\n\r\n(நீ வாகனத்தில் அமர்ந்தவாறே மக்களுக்குப் பின்னால் தவாஃப் செய்வாயாக) என்று கூறினார்கள். அவ்வாறே அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கஅபாவிற்கு அருகில் தொழுது கொண்டு ஸூரத்துத் தூர் ஓதிக் கொண்டிருந்தபோது நான் தவாஃப் செய்தேன்.\" இது புகாரியில் பதிவாகியுள்ளது.\n\r\n\n\r\nبِسْمِ اللَّهِ الرَّحْمَـنِ الرَّحِيمِ\n\r\n\n\r\nஅளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.\n\r\n\n\r\nவேதனை வருவது உறுதி என அல்லாஹ் சத்தியம் செய்தல்\n\r\n\n\r\nஅல்லாஹ் தன் படைப்புகளின் மீது சத்தியம் செய்கிறான். இது அவனது மாபெரும் ஆற்றலுக்கு ஒரு சான்றாகும். அவனது வேதனை நிச்சயமாக அவனது எதிரிகளை வந்தடையும்; அதிலிருந்து தப்பிக்க அவர்களுக்கு எந்த வழியும் இருக்காது. 'அத்-தூர்' என்பது மரங்கள் நிறைந்த மலையாகும். மூஸா (அலை) அவர்களிடம் அல்லாஹ் பேசிய மலையும், ஈஸா (அலை) அவர்களின் நபித்துவத்தை அல்லாஹ் தொடங்கிய மலையும் இது போன்றதே ஆகும். மரங்கள் இல்லாத மலை 'ஜபல்' என்று அழைக்கப்படும், 'தூர்' என்று அல்ல. அல்லாஹ் கூறினான்,\n\r\n\n\r\nوَكِتَـبٍ مُّسْطُورٍ\n\r\n\n\r\n(எழுதப்பட்ட வேதத்தின் மீதும் சத்தியமாக), இது 'அல்-லவ்ஹுல் மஹ்ஃபூழ்' (பாதுகாக்கப்பட்ட ஏடு) என்று கூறப்படுகிறது. மக்கள் ஓதும் வஹீ (இறைச்செய்தி) அருளப்பட்ட வேதங்களையும் இது குறிப்பதாகக் கூறப்படுகிறது. இதனால்தான் அல்லாஹ் கூறினான்,\n\r\n\n\r\nفِى رَقٍّ مَّنْشُورٍ - وَالْبَيْتِ الْمَعْمُورِ\n\r\n\n\r\n(விரிக்கப்பட்ட மெல்லிய தோலில் எழுதப்பட்ட வேதத்தின் மீதும், 'அல்-பைத் அல்-மஃமூர்' மீதும் சத்தியமாக.) இரண்டு ஸஹீஹ்களிலும், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் விண்வெளிப் பயணம் (இஸ்ரா) குறித்த ஹதீஸில், ஏழாவது வானத்திற்கு ஏறிச் சென்ற பிறகு இவ்வாறு கூறியுள்ளார்கள்:\n\r\n\n\r\n«ثُمَّ رُفِعَ بِي إِلَى الْبَيْتِ الْمَعْمُورِ، وَإِذَا هُوَ يَدْخُلُهُ كُلَّ يَوْمٍ سَبْعُونَ أَلْفًا، لَا يَعُودُونَ إِلَيْهِ آخِرَ مَا عَلَيْهِم»\n\r\n\n\r\n(பின்னர் நான் 'அல்-பைத் அல்-மஃமூர்'க்கு அழைத்துச் செல்லப்பட்டேன். அங்கு ஒவ்வொரு நாளும் எழுபதாயிரம் வானவர்கள் நுழைகிறார்கள். அவர்கள் அங்கிருந்து வெளியேறினால் மீண்டும் ஒருபோதும் திரும்புவதில்லை.) பூமியில் உள்ள மக்கள் கஅபாவை தவாஃப் செய்வதைப் போல வானவர்கள் 'அல்-பைத் அல்-மஃமூர்'இல் அல்லாஹ்வை வணங்கி, தவாஃப் செய்கிறார்கள். 'அல்-பைத் அல்-மஃமூர்' என்பது ஏழாவது வானத்தில் உள்ளவர்களின் கஅபா ஆகும். இஸ்ரா பயணத்தின் போது இப்ராஹீம் அல்-கலீல் (அலை) அவர்கள் 'அல்-பைத் அல்-மஃமூர்'இல் முதுகு சாய்ந்து அமர்ந்திருப்பதை நபி (ஸல்) அவர்கள் கண்டார்கள். பூமியில் கஅபாவை இப்ராஹீம் (அலை) அவர்களே கட்டினார்கள். எனவே, செயலுக்கேற்ற கூலி வழங்கப்படுகிறது. 'அல்-பைத் அல்-மஃமூர்' கஅபாவிற்கு நேர் மேலாக அமைந்துள்ளது. ஒவ்வொரு வானத்திற்கும் அதற்கென ஒரு வழிபாட்டுத் தலம் உண்டு; அதுவே அங்கு வசிப்பவர்களின் கிப்லா (தொழுகை திசை) ஆகும். கீழ் வானத்தில் உள்ள இல்லம் 'பைத் அல்-இஸ்ஸா' என்று அழைக்கப்படுகிறது. அல்லாஹ்வே மிக அறிந்தவன்.\n\r\n\n\r\nஉயர்ந்தோன் அல்லாஹ்வின் கூற்று,\n\r\n\n\r\nوَالسَّقْفِ الْمَرْفُوعِ\n\r\n\n\r\n(உயர்த்தப்பட்ட முகட்டின் மீதும் சத்தியமாக.) அலீ இப்னு அபீ தாலிப் (ரழி) அவர்கள் இதற்கு \"வானம்\" என்று விளக்கமளித்ததாக ஸுஃப்யான் அத்-தவ்ரி, ஷுஃபா மற்றும் அபூ அல்-அஹ்வஸ் ஆகியோர் ஸிமாக் மற்றும் காலித் இப்னு அர்அரா வழியாக அறிவிக்கின்றனர்.\n\r\n\n\r\nوَالسَّقْفِ الْمَرْفُوعِ\n\r\n\n\r\n(உயர்த்தப்பட்ட முகட்டின் மீதும் சத்தியமாக) என்பதற்குப் பிறகு அலீ (ரழி) அவர்கள் பின்வரும் வசனத்தை ஓதினார்கள்:\n\r\n\n\r\nوَجَعَلْنَا السَّمَآءَ سَقْفاً مَّحْفُوظاً وَهُمْ عَنْ ءَايَـتِهَا مُعْرِضُونَ\n\r\n\n\r\n(மேலும் நாம் வானத்தைப் பாதுகாக்கப்பட்ட முகடாக ஆக்கினோம். அவர்களோ அதிலுள்ள அத்தாட்சிகளைப் புறக்கணிக்கிறார்கள்.) (21:32). இதே போன்ற கருத்தையே முஜாஹித், கதாதா, அஸ்-ஸுத்தீ, இப்னு ஜுரைஜ், இப்னு ஸைத் ஆகியோரும் கூறியுள்ளனர். இப்னு ஜரீர் அவர்களும் இதனையே விரும்பத்தக்க கருத்தாகக் கொண்டுள்ளார்.\n\r\n\n\r\nஉயர்ந்தோன் அல்லாஹ்வின் கூற்று,\n\r\n\n\r\nوَالْبَحْرِ الْمَسْجُورِ\n\r\n\n\r\n('மஸ்ஜூர்' ஆன கடலின் மீதும் சத்தியமாக.) இது பூமியில் உள்ள கடல்களைக் குறிப்பதாகப் பெரும்பான்மையோர் கூறுகின்றனர். 'மஸ்ஜூர்' என்றால், மறுமை நாளில் கடல் நெருப்பால் மூட்டப்படும் என்று பொருள். அல்லாஹ் மற்றொரு வசனத்தில் கூறுவது போல்,\n\r\n\n\r\nوَإِذَا الْبِحَارُ سُجِّرَتْ\n\r\n\n\r\n(கடல்கள் தீமூட்டப்படும் போது.) (81:6) அதாவது, அது நெருப்பால் எரிக்கப்பட்டு, ஒன்றுதிரட்டப்படும் மைதானத்தில் உள்ள மக்களைச் சூழ்ந்து கொள்ளும் கொழுந்துவிட்டு எரியும் நெருப்பாக மாறும். அலீ இப்னு அபீ தாலிப் (ரழி) அவர்களிடமிருந்து ஸயீத் இப்னுல் முஸய்யிப் இதனை அறிவித்துள்ளார். இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்தும் இது அறிவிக்கப்பட்டுள்ளது. மேலும் ஸயீத் இப்னு ஜுபைர், முஜாஹித், அப்துல்லாஹ் இப்னு உபைத் இப்னு உமைர் போன்றோரின் கருத்தும் இதுவேயாகும். கதாதா கூறுகையில், \"'மஸ்ஜூர்' என்பது 'நிரப்பப்பட்ட கடல்' ஆகும்.\" இப்னு ஜரீர் இந்த விளக்கத்தையே முன்மொழிகிறார்; ஏனெனில் கடல் இப்போது நெருப்பால் எரிக்கப்படவில்லை, மாறாக அது நிரம்பியுள்ளது என்று அவர் கூறுகிறார்.\n\r\n\n\r\nஅல்லாஹ்வின் கூற்று;\n\r\n\n\r\nإِنَّ عَذَابَ رَبِّكَ لَوَاقِعٌ\n\r\n\n\r\n(நிச்சயமாக உமது இறைவனின் வேதனை நிகழ்ந்தே தீரும்.) இது சத்தியத்தின் பதிலாகும். அவனது வேதனை நிச்சயமாக நிராகரிப்பாளர்களைத் தாக்கும் என்பதை இது உணர்த்துகிறது. அல்லாஹ் மற்றோர் இடத்தில் கூறுவது போல்;\n\r\n\n\r\nمَّا لَهُ مِن دَافِعٍ\n\r\n\n\r\n(அதைத் தடுப்பவர் எவருமில்லை.) அல்லாஹ் அவர்களுக்கு வேதனையை அளிக்க முடிவு செய்துவிட்டால், அதை யாராலும் தடுக்க முடியாது. அல்-ஹாஃபிழ் அபூ பக்ர் இப்னு அபி அத்-துன்யா அவர்கள் ஜஃபர் இப்னு ஸைத் அல்-அப்தீ வாயிலாகப் பதிவு செய்துள்ளார்கள்: \"ஒருமுறை இரவு வேளையில் உமர் (ரழி) அவர்கள் மதீனாவில் மக்களின் நலனை அறியச் சென்றபோது, ஒரு மனிதர் தன் வீட்டில் உபரியான தொழுகையில் (தஹஜ்ஜுத்) ஈடுபட்டு ஓதிக் கொண்டிருப்பதைச் செவியுற்றார்கள். உமர் (ரழி) அமைதியாக நின்று அவர் ஓதுவதைக் கேட்டார்கள். அவர்,\n\r\n\n\r\nوَالطُّورِ\n\r\n\n\r\n(தூர் மலை மீது சத்தியமாக) என்று தொடங்கி, பின்வரும் வசனத்தை எட்டியபோது,\n\r\n\n\r\nإِنَّ عَذَابَ رَبِّكَ لَوَاقِعٌ - مَّا لَهُ مِن دَافِعٍ\n\r\n\n\r\n(நிச்சயமாக உமது இறைவனின் வேதனை நிகழ்ந்தே தீரும். அதைத் தடுப்பவர் எவருமில்லை.) 'கஅபாவின் இறைவன் மீது ஆணையாக! இது உண்மையான சத்தியம்' என்று உமர் (ரழி) கூறினார்கள். பின்னர் தம் கழுதையிலிருந்து இறங்கி ஒரு சுவரின் ஓரத்தில் சிறிது நேரம் அமர்ந்தார்கள். வீடு திரும்பிய அவர்கள் ஒரு மாத காலம் நோய்வாய்ப்பட்டார்கள். மக்கள் அவர்களை நலம் விசாரிக்க வந்தனர், ஆனால் அவர்களுக்கு என்ன நேர்ந்தது என்பது யாருக்கும் தெரிந்திருக்கவில்லை.\" அல்லாஹ் உமர் (ரழி) அவர்களைப் பொருந்திக் கொள்வானாக.\n\r\n\n\r\nவேதனை நாள் மற்றும் மறுமை நாள் பற்றிய விளக்கம்\n\r\n\n\r\nஅல்லாஹ் கூறினான்;\n\r\n\n\r\nيَوْمَ تَمُورُ السَّمَآءُ مَوْراً\n\r\n\n\r\n(வானம் கடுமையாக அசையும் நாளில்.) இப்னு அப்பாஸ் (ரழி) மற்றும் கதாதா ஆகியோர் \"கடுமையாக நடுங்குதல்\" என்று கூறினர். இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து \"பிளந்துவிடுதல்\" என்றும் அறிவிக்கப்பட்டுள்ளது. முஜாஹித் \"வேகமாகச் சுழலும்\" என்றார். அத்-தஹ்ஹாக் கூறுகையில், \"அல்லாஹ்வின் கட்டளையால் வானம் வேகமாகச் சுழன்று நகரும், அதன் பகுதிகள் ஒன்றோடொன்று மோதி நகரும்\" என்றார். 'மவ்ரா' என்ற சொல்லுக்குச் சுழலுதல் மற்றும் நடுங்குதல் என்ற பொருள் இருப்பதால் இப்னு ஜரீர் இதனையே சிறந்த கருத்தாகக் கொள்கிறார். அல்லாஹ் கூறினான்,\n\r\n\n\r\nوَتَسِيرُ الْجِبَالُ سَيْراً\n\r\n\n\r\n(மேலும் மலைகள் நகர்ந்து செல்லும்.) அவை மறைந்து, காற்றால் அடித்துச் செல்லப்படும் துகள்களாக மாறும்,\n\r\n\n\r\nفَوَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ\n\r\n\n\r\n(அந்நாளில் பொய்யாக்குபவர்களுக்குக் கேடுதான்.) அல்லாஹ் அவர்கள் மீது இறக்கும் வேதனை மற்றும் தண்டனையினால் அன்றைய தினம் அவர்களுக்கு அழிவு ஏற்படும்,\n\r\n\n\r\nالَّذِينَ هُمْ فِى خَوْضٍ يَلْعَبُونَ\n\r\n\n\r\n(அவர்கள் வீணானவற்றில் மூழ்கி விளையாடிக் கொண்டிருக்கிறார்கள்.) அதாவது அவர்கள் இவ்வுலகில் வீண் காரியங்களில் ஈடுபட்டு, மார்க்கத்தைப் பரிகாசப் பொருளாக ஆக்குகிறார்கள்,\n\r\n\n\r\nيَوْمَ يُدَعُّونَ\n\r\n\n\r\n(அவர்கள் பலவந்தமாகத் தள்ளப்படும் நாளில்.) அதாவது அவர்கள் வன்முறையாக இழுத்துச் செல்லப்படுவார்கள்,\n\r\n\n\r\nإِلَى نَارِ جَهَنَّمَ دَعًّا\n\r\n\n\r\n(நரக நெருப்பை நோக்கி கொடூரமாகவும் பலவந்தமாகவும் தள்ளப்படுவார்கள்.) முஜாஹித், அஷ்-ஷஃபீ, முஹம்மத் இப்னு கஅப், அத்-தஹ்ஹாக், அஸ்-ஸுத்தீ மற்றும் அத்-தவ்ரி ஆகியோர் \"அவர்கள் கடுமையாக நெருப்பிற்குள் தள்ளப்படுவார்கள்\" என்று கூறுகின்றனர். அல்லாஹ் கூறினான்,\n\r\n\n\r\nهَـذِهِ النَّارُ الَّتِى كُنتُم بِهَا تُكَذِّبُونَ\n\r\n\n\r\n(நீங்கள் எதை மறுத்துக் கொண்டிருந்தீர்களோ, அந்த நரகம் இதுதான்.) அதாவது தண்டனைக்குரிய வானவர்கள் அவர்களைக் கண்டிக்கும் விதமாக இவ்வாறு கூறுவார்கள்,\n\r\n\n\r\nأَفَسِحْرٌ هَـذَا أَمْ أَنتُمْ لاَ تُبْصِرُونَ\n\r\n\n\r\n(இது சூனியமா? அல்லது நீங்கள் பார்க்கவில்லையா?)\n\r\n\n\r\nاصْلَوْهَا\n\r\n\n\r\n(இதில் நுழைந்து கருகிவிடுங்கள்.) அதாவது 'எல்லா திசைகளிலிருந்தும் உங்களைச் சூழ்ந்து கொள்ளும் இந்த நெருப்பில் நுழையுங்கள்' என்று பொருள்.\n\r\n\n\r\nفَاصْبِرُواْ أَوْ لاَ تَصْبِرُواْ سَوَآءٌ عَلَيْكُمْ\n\r\n\n\r\n(நீங்கள் பொறுமையாக இருந்தாலும் அல்லது பொறுமையிழந்து காணப்பட்டாலும் உங்களுக்கு சமமே.) 'இதன் வேதனையை நீங்கள் சகித்துக் கொண்டாலும் இல்லாவிட்டாலும், அதிலிருந்து நீங்கள் ஒருபோதும் தப்பிக்க முடியாது.'\n\r\n\n\r\nإِنَّمَا تُجْزَوْنَ مَا كُنتُمْ تَعْمَلُونَ\n\r\n\n\r\n(நீங்கள் செய்து கொண்டிருந்தவற்றுக்கே நீங்கள் கூலி கொடுக்கப்படுகிறீர்கள்.) நிச்சயமாக அல்லாஹ் யாருக்கும் அநீதி இழைப்பதில்லை. ஒவ்வொருவருக்கும் அவரவர் செயல்களுக்கு ஏற்பவே அல்லாஹ் கூலி வழங்குகிறான்.\n\r\n\n\r\nإِنَّ الْمُتَّقِينَ فِى جَنَّـتٍ وَنَعِيمٍ - فَـكِهِينَ بِمَآ ءَاتَـهُمْ رَبُّهُمْ وَوَقَـهُمْ رَبُّهُمْ عَذَابَ الْجَحِيمِ\n\r\n\n\r\n(நிச்சயமாக இறையச்சம் உடையவர்கள், சுவர்க்கச் சோலைகளிலும், (அவற்றின்) இன்பத்திலும் இருப்பார்கள். தங்கள் இறைவன் தங்களுக்கு அளித்ததைக் கொண்டு அவர்கள் மகிழ்ந்திருப்பார்கள்; மேலும் அவர்களுடைய இறைவன் நரக வேதனையிலிருந்து அவர்களைக் காப்பாற்றி விட்டான்.)"},"17":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=52&ayah=20\" class=\"link\">52:20</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 52:20 ஐ பார்க்கவும்"},"18":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=52&ayah=20\" class=\"link\">52:20</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 52:20 ஐ பார்க்கவும்"},"19":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=52&ayah=20\" class=\"link\">52:20</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 52:20 ஐ பார்க்கவும்"},"20":{"html":"<strong>பாக்கியவான்களின் இருப்பிடம் பற்றிய விளக்கம்</strong><br />\r\n<br />\r\nஉயர்ந்தோனாகிய அல்லாஹ், வேதனையிலும் தண்டனையிலும் இருக்கும் துரதிஷ்டசாலிகளுக்கு மாற்றமாக, பாக்கியவான்களின் இருப்பிடத்தைப் பற்றி விவரிக்கும்போது,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِنَّ</span> <span class=\"quran-arabic-font text-success\">الْمُتَّقِينَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">جَنَّاتٍ</span> <span class=\"quran-arabic-font text-success\">وَنَعِيمٍ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக, இறையச்சம் (தக்வா) உடையவர்கள் சுவனச் சோலைகளிலும் இன்பத்திலும் இருப்பார்கள்) என்று கூறுகிறான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَاكِهِينَ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">آتَاهُمْ</span> <span class=\"quran-arabic-font text-success\">رَبُّهُمْ﴿</span><br />\r\n<br />\r\n(தங்கள் இறைவன் அவர்களுக்கு வழங்கியவற்றில் அவர்கள் மகிழ்ச்சியடைவார்கள்,) அதாவது, அல்லாஹ் அவர்களுக்கு அங்கு வழங்கியுள்ள பல்வேறு வகையான இன்பங்களை அவர்கள் அனுபவிப்பார்கள். உதாரணமாக, விதவிதமான உணவுகள், பானங்கள், ஆடைகள், வசிப்பிடங்கள், வாகனங்கள் போன்றவற்றை இது குறிக்கிறது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَوَقَاهُمْ</span> <span class=\"quran-arabic-font text-success\">رَبُّهُمْ</span> <span class=\"quran-arabic-font text-success\">عَذَابَ</span> <span class=\"quran-arabic-font text-success\">الْجَحِيمِ﴿</span><br />\r\n<br />\r\n(மேலும், அவர்களுடைய இறைவன் அவர்களைக் கொழுந்துவிட்டெரியும் நரக நெருப்பின் வேதனையிலிருந்து பாதுகாத்தான்.) அவன் அவர்களை நரக வேதனையிலிருந்து பாதுகாத்ததே ஒரு தனிப் பெரும் அருளாகும். அத்துடன், எந்தக் கண்ணும் கண்டிராத, எந்தக் காதும் கேட்டிராத, எந்த மனித இதயமும் கற்பனை செய்து பார்த்திராத இன்பங்கள் நிறைந்த சுவனத்தில் அவர்கள் நுழைவிக்கப்படுவது அந்த அருளை மேலும் அதிகப்படுத்துகிறது.<br />\r\n<br />\r\nஉயர்ந்தோனாகிய அல்லாஹ்வின் இக்கூற்று:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾كُلُوا</span> <span class=\"quran-arabic-font text-success\">وَاشْرَبُوا</span> <span class=\"quran-arabic-font text-success\">هَنِيئًا</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">كُنتُمْ</span> <span class=\"quran-arabic-font text-success\">تَعْمَلُونَ﴿</span><br />\r\n<br />\r\n(\"நீங்கள் செய்து கொண்டிருந்த நற்செயல்களின் காரணமாக மகிழ்ச்சியுடன் உண்ணுங்கள், பருகுங்கள்\") அவனுடைய மற்றொரு கூற்றைப் போன்றதாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾كُلُوا</span> <span class=\"quran-arabic-font text-success\">وَاشْرَبُوا</span> <span class=\"quran-arabic-font text-success\">هَنِيئًا</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">أَسْلَفْتُمْ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْأَيَّامِ</span> <span class=\"quran-arabic-font text-success\">الْخَالِيَةِ﴿</span><br />\r\n<br />\r\n(கடந்த நாட்களில் நீங்கள் முற்படுத்தி அனுப்பிய நற்செயல்களுக்காக இன்பமாக உண்ணுங்கள், பருகுங்கள்!) (<a href=\"qurandisp.php?sura=69&ayah=24\" class=\"link\">69:24</a>). அதாவது, இது உங்கள் செயல்களுக்குக் கூலியாகும்; நிச்சயமாக இவை அனைத்தும் அல்லாஹ்விடமிருந்து கிடைத்த பேரருளும் வெகுமதியுமாகும்.<br />\r\n<br />\r\nஉயர்ந்தோனாகிய அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾مُتَّكِئِينَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">سُرُرٍ</span> <span class=\"quran-arabic-font text-success\">مَّصْفُوفَةٍ﴿</span><br />\r\n<br />\r\n(அவர்கள் வரிசையாக அமைக்கப்பட்ட சிம்மாசனங்களில் (நிம்மதியாகச்) சாய்ந்திருப்பார்கள்.) அத்-தவ்ரீ அவர்கள் ஹுஸைன் வழியாக, முஜாஹித் அவர்களிடமிருந்து, இப்னு அப்பாஸ் (ரழி) அவர்கள் பின்வருமாறு கூறியதாக அறிவிக்கிறார்கள்: \"(அவை) அம்பாரிகளுக்குள் அமைக்கப்பட்ட சிம்மாசனங்கள்.\" மேலும் 'மஸ்ஃபூஃபா' (வரிசையாக அமைக்கப்பட்டவை) என்பதன் பொருள், அவர்கள் ஒருவரையொருவர் முன்னோக்கியவாறு இருப்பார்கள் என்பதாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾عَلَى</span> <span class=\"quran-arabic-font text-success\">سُرُرٍ</span> <span class=\"quran-arabic-font text-success\">مُّتَقَابِلِينَ﴿</span><br />\r\n<br />\r\n(அவர்கள் சிம்மாசனங்களின் மீது ஒருவரையொருவர் முன்னோக்கியவர்களாக இருப்பார்கள்.) (<a href=\"qurandisp.php?sura=37&ayah=44\" class=\"link\">37:44</a>)<br />\r\n<br />\r\nஅடுத்து அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَزَوَّجْنَاهُم</span> <span class=\"quran-arabic-font text-success\">بِحُورٍ</span> <span class=\"quran-arabic-font text-success\">عِينٍ﴿</span><br />\r\n<br />\r\n(மேலும், நாம் அவர்களுக்கு விசாலமான, அழகான கண்களையுடைய 'ஹூர்' (கன்னிகை)களை மணமுடித்து வைப்போம்.) நாம் அவர்களுக்காக 'அல்-ஹூர் அல்-ஈன்' இனத்தைச் சேர்ந்த நல்லொழுக்கமுள்ள, அழகான மனைவிகளைத் துணைகளாக ஆக்கினோம். 'அல்-ஹூர் அல்-ஈன்' பற்றிய விவரிப்பை இந்த தஃப்ஸீரின் பல இடங்களில் நாம் ஏற்கனவே குறிப்பிட்டுள்ளதால், அந்த விளக்கத்தை மீண்டும் இங்கு குறிப்பிடத் தேவையில்லை.<br />\r\n<br />","text":"பாக்கியவான்களின் இருப்பிடம் பற்றிய விளக்கம்\n\r\n\n\r\nஉயர்ந்தோனாகிய அல்லாஹ், வேதனையிலும் தண்டனையிலும் இருக்கும் துரதிஷ்டசாலிகளுக்கு மாற்றமாக, பாக்கியவான்களின் இருப்பிடத்தைப் பற்றி விவரிக்கும்போது,\n\r\n\n\r\n﴾إِنَّ الْمُتَّقِينَ فِي جَنَّاتٍ وَنَعِيمٍ﴿\n\r\n\n\r\n(நிச்சயமாக, இறையச்சம் (தக்வா) உடையவர்கள் சுவனச் சோலைகளிலும் இன்பத்திலும் இருப்பார்கள்) என்று கூறுகிறான்.\n\r\n\n\r\n﴾فَاكِهِينَ بِمَا آتَاهُمْ رَبُّهُمْ﴿\n\r\n\n\r\n(தங்கள் இறைவன் அவர்களுக்கு வழங்கியவற்றில் அவர்கள் மகிழ்ச்சியடைவார்கள்,) அதாவது, அல்லாஹ் அவர்களுக்கு அங்கு வழங்கியுள்ள பல்வேறு வகையான இன்பங்களை அவர்கள் அனுபவிப்பார்கள். உதாரணமாக, விதவிதமான உணவுகள், பானங்கள், ஆடைகள், வசிப்பிடங்கள், வாகனங்கள் போன்றவற்றை இது குறிக்கிறது.\n\r\n\n\r\n﴾وَوَقَاهُمْ رَبُّهُمْ عَذَابَ الْجَحِيمِ﴿\n\r\n\n\r\n(மேலும், அவர்களுடைய இறைவன் அவர்களைக் கொழுந்துவிட்டெரியும் நரக நெருப்பின் வேதனையிலிருந்து பாதுகாத்தான்.) அவன் அவர்களை நரக வேதனையிலிருந்து பாதுகாத்ததே ஒரு தனிப் பெரும் அருளாகும். அத்துடன், எந்தக் கண்ணும் கண்டிராத, எந்தக் காதும் கேட்டிராத, எந்த மனித இதயமும் கற்பனை செய்து பார்த்திராத இன்பங்கள் நிறைந்த சுவனத்தில் அவர்கள் நுழைவிக்கப்படுவது அந்த அருளை மேலும் அதிகப்படுத்துகிறது.\n\r\n\n\r\nஉயர்ந்தோனாகிய அல்லாஹ்வின் இக்கூற்று:\n\r\n\n\r\n﴾كُلُوا وَاشْرَبُوا هَنِيئًا بِمَا كُنتُمْ تَعْمَلُونَ﴿\n\r\n\n\r\n(\"நீங்கள் செய்து கொண்டிருந்த நற்செயல்களின் காரணமாக மகிழ்ச்சியுடன் உண்ணுங்கள், பருகுங்கள்\") அவனுடைய மற்றொரு கூற்றைப் போன்றதாகும்:\n\r\n\n\r\n﴾كُلُوا وَاشْرَبُوا هَنِيئًا بِمَا أَسْلَفْتُمْ فِي الْأَيَّامِ الْخَالِيَةِ﴿\n\r\n\n\r\n(கடந்த நாட்களில் நீங்கள் முற்படுத்தி அனுப்பிய நற்செயல்களுக்காக இன்பமாக உண்ணுங்கள், பருகுங்கள்!) (69:24). அதாவது, இது உங்கள் செயல்களுக்குக் கூலியாகும்; நிச்சயமாக இவை அனைத்தும் அல்லாஹ்விடமிருந்து கிடைத்த பேரருளும் வெகுமதியுமாகும்.\n\r\n\n\r\nஉயர்ந்தோனாகிய அல்லாஹ் கூறினான்:\n\r\n\n\r\n﴾مُتَّكِئِينَ عَلَى سُرُرٍ مَّصْفُوفَةٍ﴿\n\r\n\n\r\n(அவர்கள் வரிசையாக அமைக்கப்பட்ட சிம்மாசனங்களில் (நிம்மதியாகச்) சாய்ந்திருப்பார்கள்.) அத்-தவ்ரீ அவர்கள் ஹுஸைன் வழியாக, முஜாஹித் அவர்களிடமிருந்து, இப்னு அப்பாஸ் (ரழி) அவர்கள் பின்வருமாறு கூறியதாக அறிவிக்கிறார்கள்: \"(அவை) அம்பாரிகளுக்குள் அமைக்கப்பட்ட சிம்மாசனங்கள்.\" மேலும் 'மஸ்ஃபூஃபா' (வரிசையாக அமைக்கப்பட்டவை) என்பதன் பொருள், அவர்கள் ஒருவரையொருவர் முன்னோக்கியவாறு இருப்பார்கள் என்பதாகும்:\n\r\n\n\r\n﴾عَلَى سُرُرٍ مُّتَقَابِلِينَ﴿\n\r\n\n\r\n(அவர்கள் சிம்மாசனங்களின் மீது ஒருவரையொருவர் முன்னோக்கியவர்களாக இருப்பார்கள்.) (37:44)\n\r\n\n\r\nஅடுத்து அல்லாஹ் கூறினான்:\n\r\n\n\r\n﴾وَزَوَّجْنَاهُم بِحُورٍ عِينٍ﴿\n\r\n\n\r\n(மேலும், நாம் அவர்களுக்கு விசாலமான, அழகான கண்களையுடைய 'ஹூர்' (கன்னிகை)களை மணமுடித்து வைப்போம்.) நாம் அவர்களுக்காக 'அல்-ஹூர் அல்-ஈன்' இனத்தைச் சேர்ந்த நல்லொழுக்கமுள்ள, அழகான மனைவிகளைத் துணைகளாக ஆக்கினோம். 'அல்-ஹூர் அல்-ஈன்' பற்றிய விவரிப்பை இந்த தஃப்ஸீரின் பல இடங்களில் நாம் ஏற்கனவே குறிப்பிட்டுள்ளதால், அந்த விளக்கத்தை மீண்டும் இங்கு குறிப்பிடத் தேவையில்லை."},"21":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=52&ayah=28\" class=\"link\">52:28</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 52:28 ஐ பார்க்கவும்"},"22":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=52&ayah=28\" class=\"link\">52:28</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 52:28 ஐ பார்க்கவும்"},"23":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=52&ayah=28\" class=\"link\">52:28</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 52:28 ஐ பார்க்கவும்"},"24":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=52&ayah=28\" class=\"link\">52:28</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 52:28 ஐ பார்க்கவும்"},"25":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=52&ayah=28\" class=\"link\">52:28</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 52:28 ஐ பார்க்கவும்"},"26":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=52&ayah=28\" class=\"link\">52:28</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 52:28 ஐ பார்க்கவும்"},"27":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=52&ayah=28\" class=\"link\">52:28</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 52:28 ஐ பார்க்கவும்"},"28":{"html":"<strong>நல்லறம் புரிந்த இறைநம்பிக்கையாளர்களின் சந்ததியினர் சுவர்க்கத்தில் அவர்களின் அந்தஸ்துகளுக்கு உயர்த்தப்படுவார்கள்</strong><br />\r\n<br />\r\nஇந்த வசனத்தில், கண்ணியமிக்க அல்லாஹ் தனது படைப்புகளின் மீது தான் பொழியும் பேரருள், தாராளத்தன்மை, கருணை மற்றும் நன்மையை உறுதிப்படுத்துகிறான். நல்லறம் புரிந்த இறைநம்பிக்கையாளர்களின் சந்ததியினர், ஈமானில் (நம்பிக்கையில்) தங்கள் பெற்றோரைப் பின்பற்றும் போது, அச்சந்ததியினர் தங்கள் பெற்றோரைப் போன்று நற்செயல்கள் செய்யாவிட்டாலும், அல்லாஹ் அவர்களைப் பெற்றோர்களின் அந்தஸ்துக்கு உயர்த்துவான். தங்கள் சந்ததியினர் தங்களின் அந்தஸ்துக்கு உயர்த்தப்படுவதைக் காண்பதன் மூலம் அல்லாஹ் பெற்றோர்களின் கண்களைக் குளிர்விப்பான். நிச்சயமாக, அல்லாஹ் அவர்களை மிகச்சிறந்த முறையில் ஒன்று சேர்ப்பான். மேலும், அவர்களை ஒன்று சேர்ப்பதற்காக உயர்ந்த அந்தஸ்தில் உள்ளவர்களின் நற்கூலியையோ அல்லது அந்தஸ்துகளையோ அவன் குறைக்கமாட்டான். இதையே அவன் பின்வருமாறு கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَلْحَقْنَا</span> <span class=\"quran-arabic-font text-success\">بِهِمْ</span> <span class=\"quran-arabic-font text-success\">ذُرِّيَّتَهُمْ</span> <span class=\"quran-arabic-font text-success\">وَمَآ</span> <span class=\"quran-arabic-font text-success\">أَلَتْنَاهُمْ</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">عَمَلِهِم</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">شَىْءٍ</span><br />\r\n<br />\r\n(அவர்களுடன் அவர்களுடைய சந்ததிகளை நாம் சேர்ப்போம்; மேலும், அவர்களுடைய செயல்களின் நற்கூலியில் எதையும் நாம் குறைக்கமாட்டோம்.) இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அத்-தவ்ரீ அறிவிக்கிறார்கள்: \"நிச்சயமாக அல்லாஹ், இறைநம்பிக்கையாளர்களின் சந்ததியினர் தங்கள் பெற்றோரைப் போன்று நற்செயல்கள் செய்யாவிட்டாலும், பெற்றோர்களின் கண்கள் குளிர்ச்சியடைவதற்காக அவர்களின் அந்தஸ்தைப் பெற்றோர்களின் நிலைக்கு உயர்த்துகிறான்.\" பின்னர் இப்னு அப்பாஸ் (ரழி) அவர்கள் இந்த வசனத்தை ஓதினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">آمَنُوا</span> <span class=\"quran-arabic-font text-success\">وَاتَّبَعَتْهُمْ</span> <span class=\"quran-arabic-font text-success\">ذُرِّيَّتُهُم</span> <span class=\"quran-arabic-font text-success\">بِإِيمَانٍ</span> <span class=\"quran-arabic-font text-success\">أَلْحَقْنَا</span> <span class=\"quran-arabic-font text-success\">بِهِمْ</span> <span class=\"quran-arabic-font text-success\">ذُرِّيَّتَهُمْ</span> <span class=\"quran-arabic-font text-success\">وَمَآ</span> <span class=\"quran-arabic-font text-success\">أَلَتْنَاهُمْ</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">عَمَلِهِم</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">شَىْءٍ</span><br />\r\n<br />\r\n(மேலும் எவர்கள் ஈமான் கொண்டு, அவர்களைப் பின்பற்றி அவர்களுடைய சந்ததியினரும் ஈமான் கொள்கிறார்களோ, அவர்களுடன் அவர்களுடைய சந்ததிகளை நாம் சேர்ப்போம்; மேலும் அவர்களுடைய செயல்களின் நற்கூலியில் எதையும் நாம் குறைக்கமாட்டோம்.) இப்னு ஜரீர் மற்றும் இப்னு அபீ ஹாதிம் ஆகியோர் இக்கருத்தை ஸுஃப்யான் அத்-தவ்ரீ வழியாக இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து பதிவு செய்துள்ளனர். அல்லாஹ்வின் கூற்றிற்கு இப்னு அப்பாஸ் (ரழி) அவர்கள் அளித்த விளக்கத்தை இப்னு அபீ ஹாதிம் பின்வருமாறு பதிவு செய்துள்ளார்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">آمَنُوا</span> <span class=\"quran-arabic-font text-success\">وَاتَّبَعَتْهُمْ</span> <span class=\"quran-arabic-font text-success\">ذُرِّيَّتُهُم</span> <span class=\"quran-arabic-font text-success\">بِإِيمَانٍ</span> <span class=\"quran-arabic-font text-success\">أَلْحَقْنَا</span> <span class=\"quran-arabic-font text-success\">بِهِمْ</span> <span class=\"quran-arabic-font text-success\">ذُرِّيَّتَهُمْ</span><br />\r\n<br />\r\n(மேலும் எவர்கள் ஈமான் கொண்டு, அவர்களைப் பின்பற்றி அவர்களுடைய சந்ததியினரும் ஈமான் கொள்கிறார்களோ, அவர்களுடன் அவர்களுடைய சந்ததிகளை நாம் சேர்ப்போம்.) என்று கூறிவிட்டு, \"இவர்கள் ஈமானுடன் மரணித்த இறைநம்பிக்கையாளர்களின் சந்ததியினர் ஆவர். பெற்றோர்களின் அந்தஸ்து இவர்களின் அந்தஸ்தை விட உயர்வாக இருந்தால், அவர்கள் பெற்றோர்களுடன் சேர்த்து வைக்கப்படுவார்கள். இதற்காக பெற்றோர்கள் செய்த நற்செயல்களுக்குரிய கூலியில் எந்தக் குறைவும் செய்யப்படாது\" என்று விளக்கமளித்தார்கள். இமாம் அஹ்மதின் மகனான அப்துல்லாஹ் பதிவு செய்துள்ளதாவது: அலி (ரழி) அவர்கள் கூறினார்கள், \"கதீஜா (ரழி) அவர்கள் ஜாஹிலிய்யா (அறியாமை) காலத்தில் மரணித்த தனது இரு குழந்தைகளைப் பற்றி நபிகளாரிடம் கேட்டார்கள். அதற்கு அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">هُمَا</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">النَّار</span>»<br />\r\n<br />\r\n(அவ்விருவரும் நரக நெருப்பில் உள்ளனர்) என்று கூறினார்கள். கதீஜா (ரழி) அவர்களின் முகத்தில் சோகத்தைக் கண்டபோது, நபிகளார் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">لَوْ</span> <span class=\"quran-arabic-font text-success\">رَأَيْتِ</span> <span class=\"quran-arabic-font text-success\">مَكَانَهُمَا</span> <span class=\"quran-arabic-font text-success\">لَأَبْغَضْتِهِمَا</span>»<br />\r\n<br />\r\n(அவர்கள் இருக்குமிடத்தை நீ பார்த்தால் அவர்களை நீ வெறுத்திருப்பாய்.) அதற்கு அவர், 'அல்லாஹ்வின் தூதரே! உங்களுடன் எனக்குப் பிறந்த குழந்தைகளின் நிலை என்ன?' என்று கேட்டார். அதற்கு நபிகளார் (ஸல்) அவர்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْجَنَّة</span>»<br />\r\n<br />\r\n(அவர்கள் சுவர்க்கத்தில் உள்ளனர்) என்று கூறினார்கள். தொடர்ந்து அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنِينَ</span> <span class=\"quran-arabic-font text-success\">وَأَوْلَادَهُمْ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ،</span> <span class=\"quran-arabic-font text-success\">وَإِنَّ</span> <span class=\"quran-arabic-font text-success\">الْمُشْرِكِينَ</span> <span class=\"quran-arabic-font text-success\">وَأَوْلَادَهُمْ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">النَّار</span>»<br />\r\n<br />\r\n(நிச்சயமாக இறைநம்பிக்கையாளர்களும் அவர்களின் சந்ததியினரும் சுவர்க்கத்தில் இருப்பார்கள்; இணைவைப்பாளர்களும் அவர்களின் சந்ததியினரும் நரக நெருப்பில் இருப்பார்கள்.) பின்னர் நபி (ஸல்) அவர்கள் இந்த வசனத்தை ஓதினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">آمَنُوا</span> <span class=\"quran-arabic-font text-success\">وَاتَّبَعَتْهُمْ</span> <span class=\"quran-arabic-font text-success\">ذُرِّيَّتُهُم</span> <span class=\"quran-arabic-font text-success\">بِإِيمَانٍ</span><br />\r\n<br />\r\n(மேலும் எவர்கள் ஈமான் கொண்டு, அவர்களைப் பின்பற்றி அவர்களுடைய சந்ததியினரும் ஈமான் கொள்கிறார்களோ...)\" பெற்றோர்களின் நற்செயல்களின் காரணமாக அல்லாஹ் பிள்ளைகளுக்கு இந்த பாக்கியத்தை வழங்குவது அவனது பேரருளும் கிருபையுமாகும். அதேபோல், பிள்ளைகள் பெற்றோர்களுக்காகப் பிரார்த்திப்பதன் காரணமாக, பெற்றோர்களுக்கும் அல்லாஹ் தனது அருளை வழங்குகிறான். அபூ ஹுரைரா (ரழி) அவர்கள் அறிவித்ததாக இமாம் அஹ்மத் பதிவு செய்துள்ளார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">اللهَ</span> <span class=\"quran-arabic-font text-success\">لَيَرْفَعُ</span> <span class=\"quran-arabic-font text-success\">الدَّرَجَةَ</span> <span class=\"quran-arabic-font text-success\">لِلْعَبْدِ</span> <span class=\"quran-arabic-font text-success\">الصَّالِحِ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ</span> <span class=\"quran-arabic-font text-success\">فَيَقُولُ</span>: <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">رَبِّ</span> <span class=\"quran-arabic-font text-success\">أَنَّى</span> <span class=\"quran-arabic-font text-success\">لِي</span> <span class=\"quran-arabic-font text-success\">هذِهِ؟</span> <span class=\"quran-arabic-font text-success\">فَيَقُولُ</span>: <span class=\"quran-arabic-font text-success\">بِاسْتِغْفَارِ</span> <span class=\"quran-arabic-font text-success\">وَلَدِكَ</span> <span class=\"quran-arabic-font text-success\">لَك</span>»<br />\r\n<br />\r\n(நிச்சயமாக அல்லாஹ் சுவர்க்கத்தில் ஒரு நல்லடியாரின் அந்தஸ்தை உயர்த்துகிறான். அப்போது அவர், \"என் இறைவா! இது எனக்கு எப்படி கிடைத்தது?\" என்று கேட்பார். அதற்கு அல்லாஹ், \"உனது பிள்ளை உனக்காகப் பாவமன்னிப்புத் தேடியதால்\" என்று பதிலளிப்பான்.) இந்த ஹதீஸின் அறிவிப்பாளர் தொடர் ஆதாரபூர்வமானது, ஆனால் இது ஸஹீஹ் நூல்களில் இந்த வடிவில் இடம்பெறவில்லை. எனினும், ஸஹீஹ் முஸ்லிமில் அபூ ஹுரைரா (ரழி) அவர்களின் அறிவிப்பில் இதற்குச் சான்றாக ஒரு ஹதீஸ் உள்ளது. அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">مَاتَ</span> <span class=\"quran-arabic-font text-success\">ابْنُ</span> <span class=\"quran-arabic-font text-success\">آدَمَ</span> <span class=\"quran-arabic-font text-success\">انْقَطَعَ</span> <span class=\"quran-arabic-font text-success\">عَمَلُهُ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">ثَلَاثٍ</span>: <span class=\"quran-arabic-font text-success\">صَدَقَةٍ</span> <span class=\"quran-arabic-font text-success\">جَارِيَةٍ،</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">عِلْمٍ</span> <span class=\"quran-arabic-font text-success\">يُنْتَفَعُ</span> <span class=\"quran-arabic-font text-success\">بِهِ،</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">وَلَدٍ</span> <span class=\"quran-arabic-font text-success\">صَالِحٍ</span> <span class=\"quran-arabic-font text-success\">يَدْعُو</span> <span class=\"quran-arabic-font text-success\">لَه</span>»<br />\r\n<br />\r\n(ஆதமின் மகன் மரணிக்கும்போது, மூன்றைத் தவிர அவனது செயல்கள் யாவும் நின்றுவிடுகின்றன: அவை: நிலையான தர்மம், பிறர் பயனடையும் கல்வி மற்றும் அவனுக்காகப் பிரார்த்தனை செய்யும் ஒரு நல்ல பிள்ளை.)<br />\r\n<br />\r\n<strong>அல்லாஹ் பாவிகளிடம் நீதியாக நடந்துகொள்கிறான்</strong><br />\r\n<br />\r\nஉயர்ந்தோன் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كُلُّ</span> <span class=\"quran-arabic-font text-success\">امْرِىءٍ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">كَسَبَ</span> <span class=\"quran-arabic-font text-success\">رَهِينٌ</span><br />\r\n<br />\r\n(ஒவ்வொரு மனிதனும் தான் சம்பாதித்தவற்றுக்குப் பிணையாக இருக்கிறான்.) சந்ததியினரின் நற்செயல்கள் பெற்றோர்களின் நிலைக்குத் தகுதி பெறாவிட்டாலும், அவர்களை பெற்றோர்களின் அந்தஸ்துக்கு உயர்த்தும் தனது அருளைக் குறிப்பிட்ட பிறகு, மற்றவர்களின் தவறுகளுக்காக அல்லாஹ் யாரையும் தண்டிப்பதில்லை என்ற தனது நீதியை அவன் இங்கே உறுதிப்படுத்துகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كُلُّ</span> <span class=\"quran-arabic-font text-success\">امْرِىءٍ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">كَسَبَ</span> <span class=\"quran-arabic-font text-success\">رَهِينٌ</span><br />\r\n<br />\r\n(ஒவ்வொரு மனிதனும் தான் சம்பாதித்தவற்றுக்குப் பிணையாக இருக்கிறான்.) எனவே, ஒவ்வொரு மனிதனும் தனது சொந்தச் செயல்களுக்குப் பொறுப்பாவான். மற்றவர்கள் செய்த பாவம், அது பெற்றோர்களோ அல்லது பிள்ளைகளோ செய்ததாக இருந்தாலும், ஒருவரது சுமையுடன் சேர்க்கப்படாது. இது பற்றி அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كُلُّ</span> <span class=\"quran-arabic-font text-success\">نَفْسٍ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">كَسَبَتْ</span> <span class=\"quran-arabic-font text-success\">رَهِينَةٌ</span> - <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">أَصْحَابَ</span> <span class=\"quran-arabic-font text-success\">الْيَمِينِ</span> - <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">جَنَّاتٍ</span> <span class=\"quran-arabic-font text-success\">يَتَسَاءَلُونَ</span> - <span class=\"quran-arabic-font text-success\">عَنِ</span> <span class=\"quran-arabic-font text-success\">الْمُجْرِمِينَ</span><br />\r\n<br />\r\n(ஒவ்வோர் ஆத்மாவும் தான் செய்தவற்றுக்குப் பிணையாகவே இருக்கும். வலப்புறத்தாரைத் தவிர. அவர்கள் சுவர்க்கச் சோலைகளில் இருந்துகொண்டு, குற்றவாளிகளைப் பற்றி விசாரிப்பார்கள்.) (<a href=\"qurandisp.php?sura=74&ayah=38\" class=\"link\">74:38</a>-41)<br />\r\n<br />\r\n<strong>சுவர்க்கத்தின் மது மற்றும் அங்கிருப்பவர்களின் இன்பங்கள் பற்றிய விவரிப்பு</strong><br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَمْدَدْنَاهُم</span> <span class=\"quran-arabic-font text-success\">بِفَاكِهَةٍ</span> <span class=\"quran-arabic-font text-success\">وَلَحْمٍ</span> <span class=\"quran-arabic-font text-success\">مِّمَّا</span> <span class=\"quran-arabic-font text-success\">يَشْتَهُونَ</span><br />\r\n<br />\r\n(மேலும், அவர்கள் விரும்பக்கூடிய பழங்களையும் இறைச்சியையும் அவர்களுக்கு நாம் தாராளமாக வழங்குவோம்.) அதாவது, அவர்கள் எதை ஆசைப்படுகிறார்களோ, எதை விரும்புகிறார்களோ அத்தகைய பலவிதமான பழங்களையும் இறைச்சிகளையும் நாம் அவர்களுக்கு வழங்குவோம்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَتَنَازَعُونَ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">كَأْساً</span><br />\r\n<br />\r\n(அங்கே அவர்கள் ஒரு கோப்பையை ஒருவருக்கொருவர் கைமாற்றிக் கொள்வார்கள்.) அத்-தஹ்ஹாக் கூறுகிறார்கள், இதன் பொருள் 'மதுக் கோப்பை' என்பதாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">لَغْوٌ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَأْثِيمٌ</span><br />\r\n<br />\r\n(அதில் வீணான பேச்சோ அல்லது பாவமான செயலோ இருக்காது.) அதாவது, அவர்கள் அதைப் பருகும்போது, இவ்வுலகக் குடிகாரர்களைப் போன்று வீணான வார்த்தைகளையோ அல்லது அசிங்கமான, பாவமான பேச்சுகளையோ பேசமாட்டார்கள். இப்னு அப்பாஸ் (ரழி) அவர்கள், 'லக்வ்' என்பது பொய்யையும், 'தஃதீம்' என்பது பொய் பேசுவதையும் குறிக்கும் என்கிறார்கள். முஜாஹித் கூறுகையில், \"அவர்கள் ஒருவரையொருவர் திட்ட மாட்டார்கள்; பாவம் செய்ய மாட்டார்கள்\" என்கிறார். கதாதா கூறுகையில், \"மதுவினால் இவ்வுலகில் ஏற்படும் தீய விளைவுகளில் ஷைத்தான் உதவி செய்கிறான். ஆனால், இவ்வுலக மதுவினால் ஏற்படும் தீமைகள் மற்றும் பாதிப்புகளிலிருந்து மறுமையின் மதுவை அல்லாஹ் தூய்மைப்படுத்தினான்\" என்கிறார். எனவே, தலைவலி, வயிற்றுவலி மற்றும் போதையை உண்டாக்கும் இவ்வுலக மதுவின் தன்மையிலிருந்து மறுமையின் மதுவை அல்லாஹ் பரிசுத்தமாக்கியுள்ளான். மறுமையின் மதுவைப் பருகுபவர்கள் எவ்விதப் பயனுமற்ற, முட்டாள்தனமான அல்லது தீய வார்த்தைகளைப் பேசமாட்டார்கள் என்று அல்லாஹ் கூறுகிறான். மேலும், மறுமையின் மது தோற்றத்தில் அழகாகவும், சுவையாகவும் இருக்கும் என்று அல்லாஹ் வர்ணிக்கிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بَيْضَاءَ</span> <span class=\"quran-arabic-font text-success\">لَذَّةٍ</span> <span class=\"quran-arabic-font text-success\">لِلشَّارِبِينَ</span> - <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">غَوْلٌ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">هُمْ</span> <span class=\"quran-arabic-font text-success\">عَنْهَا</span> <span class=\"quran-arabic-font text-success\">يُنزَفُونَ</span><br />\r\n<br />\r\n(அது வெண்மையானது, அருந்துபவர்களுக்குச் சுவையானது. அதில் எவ்விதத் தீங்கும் இல்லை; அதனால் அவர்கள் போதை கொள்ளவும் மாட்டார்கள்.) (<a href=\"qurandisp.php?sura=37&ayah=46\" class=\"link\">37:46</a>-47). மேலும்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">يُصَدَّعُونَ</span> <span class=\"quran-arabic-font text-success\">عَنْهَا</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">يُنزِفُونَ</span><br />\r\n<br />\r\n(அதனால் அவர்களுக்குத் தலைவலியோ அல்லது போதையோ ஏற்படாது.) (<a href=\"qurandisp.php?sura=56&ayah=19\" class=\"link\">56:19</a>). உயர்ந்தோன் அல்லாஹ் இங்கே கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَتَنَازَعُونَ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">كَأْساً</span> <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">لَغْوٌ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَأْثِيمٌ</span><br />\r\n<br />\r\n(அங்கே அவர்கள் ஒரு (மதுக்) கோப்பையை ஒருவருக்கொருவர் கைமாற்றிக் கொள்வார்கள்; அதில் வீண் பேச்சோ அல்லது பாவமோ இருக்காது.) அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَيَطُوفُ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">غِلْمَانٌ</span> <span class=\"quran-arabic-font text-success\">لَّهُمْ</span> <span class=\"quran-arabic-font text-success\">كَأَنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">لُؤْلُؤٌ</span> <span class=\"quran-arabic-font text-success\">مَّكْنُونٌ</span><br />\r\n<br />\r\n(மேலும், அவர்களுக்குப் பணிவிடை செய்வதற்காகப் பாதுகாக்கப்பட்ட முத்துக்களைப் போன்ற சிறுவர்கள் அவர்களைச் சுற்றி வருவார்கள்.) இது சுவர்க்கத்தில் இறைநம்பிக்கையாளர்களுக்குக் கிடைக்கும் உதவியாளர்களைப் பற்றிய விவரிப்பாகும். அச்சிறுவர்கள் பாதுகாக்கப்பட்ட முத்துக்களைப் போன்று அழகாகவும், நேர்த்தியாகவும், சுத்தமாகவும் இருப்பார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَطُوفُ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">وِلْدَانٌ</span> <span class=\"quran-arabic-font text-success\">مُّخَلَّدُونَ</span> - <span class=\"quran-arabic-font text-success\">بِأَكْوَابٍ</span> <span class=\"quran-arabic-font text-success\">وَأَبَارِيقَ</span> <span class=\"quran-arabic-font text-success\">وَكَأْسٍ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">مَّعِينٍ</span><br />\r\n<br />\r\n(என்றும் இளமையுடன் இருக்கும் சிறுவர்கள் கிண்ணங்களுடனும், ஜாடிகளுடனும், தெளிந்த மது நிறைந்த கோப்பையுடனும் அவர்களைச் சுற்றி வருவார்கள்.) (<a href=\"qurandisp.php?sura=56&ayah=17\" class=\"link\">56:17</a>-18) உயர்ந்தோன் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَقْبَلَ</span> <span class=\"quran-arabic-font text-success\">بَعْضُهُمْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">بَعْضٍ</span> <span class=\"quran-arabic-font text-success\">يَتَسَاءَلُونَ</span><br />\r\n<br />\r\n(மேலும் அவர்களில் ஒருவர் மற்றவரை முன்னோக்கி நலம் விசாரித்துக் கொள்வார்கள்.) அதாவது, இறைநம்பிக்கையாளர்கள் ஒருவருக்கொருவர் நெருங்கி, இவ்வுலகில் தாங்கள் செய்த செயல்களையும் தாங்கள் இருந்த நிலைகளையும் பற்றிப் பேசிக்கொள்வார்கள். இவ்வுலகில் மக்கள் ஒன்றுகூடி மது அருந்தும்போது, குறிப்பாகப் போதையில் பேசிக்கொள்வதைப் போன்று (ஆனால் பரிசுத்தமான முறையில்) உரையாடுவார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">كُنَّا</span> <span class=\"quran-arabic-font text-success\">قَبْلُ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">أَهْلِنَا</span> <span class=\"quran-arabic-font text-success\">مُشْفِقِينَ</span><br />\r\n<br />\r\n(அவர்கள் கூறுவார்கள்: \"நிச்சயமாக நாம் இதற்கு முன்னால் நம் குடும்பத்தினரிடையே (அல்லாஹ்வைப் பற்றி) அஞ்சியவர்களாக இருந்தோம்.\") அதாவது, \"இவ்வுலக வாழ்க்கையில் நம் குடும்பத்தாருடன் இருந்தபோது நம் இறைவனைப் பற்றியும், அவனது வேதனை மற்றும் தண்டனையைப் பற்றியும் நாம் அஞ்சினோம்\" என்பதாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَمَنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">عَلَيْنَا</span> <span class=\"quran-arabic-font text-success\">وَوَقَانَا</span> <span class=\"quran-arabic-font text-success\">عَذَابَ</span> <span class=\"quran-arabic-font text-success\">السَّمُومِ</span><br />\r\n<br />\r\n(ஆகவே அல்லாஹ் நம் மீது பேரருள் புரிந்து, நச்சுக்காற்றின் (நரகின்) வேதனையிலிருந்து நம்மைக் காப்பாற்றினான்.) அதாவது, \"அவன் நமக்குக் கிருபை செய்து, நாம் எதைப் பயந்தோமோ அதிலிருந்து நம்மைக் காப்பாற்றினான்\" என்பதாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">كُنَّا</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلُ</span> <span class=\"quran-arabic-font text-success\">نَدْعُوهُ</span><br />\r\n<br />\r\n(நிச்சயமாக நாம் இதற்கு முன்னரே அவனை அழைத்து (பிரார்த்தித்து) வந்தோம்.) அதாவது, \"பணிவுடனும் தாழ்மையுடனும் அவனிடம் நாம் பிரார்த்தனை செய்து வந்தோம். அவன் நம் பிரார்த்தனையை ஏற்று, நாம் விரும்பியதை நமக்கு வழங்கினான்.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">الْبَرُّ</span> <span class=\"quran-arabic-font text-success\">الرَّحِيمُ</span><br />\r\n<br />\r\n(நிச்சயமாக அவன் மிக்க நன்மை செய்பவன்; மகா கருணையாளன்.) அதாவது, எமது பிரார்த்தனையை அவன் அங்கீகரித்தான்; எமது கோரிக்கையை ஏற்றான்; நாம் ஆதரவு வைத்திருந்ததை நமக்கு அளித்தான்.<br />\r\n<br />","text":"நல்லறம் புரிந்த இறைநம்பிக்கையாளர்களின் சந்ததியினர் சுவர்க்கத்தில் அவர்களின் அந்தஸ்துகளுக்கு உயர்த்தப்படுவார்கள்\n\r\n\n\r\nஇந்த வசனத்தில், கண்ணியமிக்க அல்லாஹ் தனது படைப்புகளின் மீது தான் பொழியும் பேரருள், தாராளத்தன்மை, கருணை மற்றும் நன்மையை உறுதிப்படுத்துகிறான். நல்லறம் புரிந்த இறைநம்பிக்கையாளர்களின் சந்ததியினர், ஈமானில் (நம்பிக்கையில்) தங்கள் பெற்றோரைப் பின்பற்றும் போது, அச்சந்ததியினர் தங்கள் பெற்றோரைப் போன்று நற்செயல்கள் செய்யாவிட்டாலும், அல்லாஹ் அவர்களைப் பெற்றோர்களின் அந்தஸ்துக்கு உயர்த்துவான். தங்கள் சந்ததியினர் தங்களின் அந்தஸ்துக்கு உயர்த்தப்படுவதைக் காண்பதன் மூலம் அல்லாஹ் பெற்றோர்களின் கண்களைக் குளிர்விப்பான். நிச்சயமாக, அல்லாஹ் அவர்களை மிகச்சிறந்த முறையில் ஒன்று சேர்ப்பான். மேலும், அவர்களை ஒன்று சேர்ப்பதற்காக உயர்ந்த அந்தஸ்தில் உள்ளவர்களின் நற்கூலியையோ அல்லது அந்தஸ்துகளையோ அவன் குறைக்கமாட்டான். இதையே அவன் பின்வருமாறு கூறுகிறான்:\n\r\n\n\r\nأَلْحَقْنَا بِهِمْ ذُرِّيَّتَهُمْ وَمَآ أَلَتْنَاهُمْ مِّنْ عَمَلِهِم مِّن شَىْءٍ\n\r\n\n\r\n(அவர்களுடன் அவர்களுடைய சந்ததிகளை நாம் சேர்ப்போம்; மேலும், அவர்களுடைய செயல்களின் நற்கூலியில் எதையும் நாம் குறைக்கமாட்டோம்.) இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அத்-தவ்ரீ அறிவிக்கிறார்கள்: \"நிச்சயமாக அல்லாஹ், இறைநம்பிக்கையாளர்களின் சந்ததியினர் தங்கள் பெற்றோரைப் போன்று நற்செயல்கள் செய்யாவிட்டாலும், பெற்றோர்களின் கண்கள் குளிர்ச்சியடைவதற்காக அவர்களின் அந்தஸ்தைப் பெற்றோர்களின் நிலைக்கு உயர்த்துகிறான்.\" பின்னர் இப்னு அப்பாஸ் (ரழி) அவர்கள் இந்த வசனத்தை ஓதினார்கள்:\n\r\n\n\r\nوَالَّذِينَ آمَنُوا وَاتَّبَعَتْهُمْ ذُرِّيَّتُهُم بِإِيمَانٍ أَلْحَقْنَا بِهِمْ ذُرِّيَّتَهُمْ وَمَآ أَلَتْنَاهُمْ مِّنْ عَمَلِهِم مِّن شَىْءٍ\n\r\n\n\r\n(மேலும் எவர்கள் ஈமான் கொண்டு, அவர்களைப் பின்பற்றி அவர்களுடைய சந்ததியினரும் ஈமான் கொள்கிறார்களோ, அவர்களுடன் அவர்களுடைய சந்ததிகளை நாம் சேர்ப்போம்; மேலும் அவர்களுடைய செயல்களின் நற்கூலியில் எதையும் நாம் குறைக்கமாட்டோம்.) இப்னு ஜரீர் மற்றும் இப்னு அபீ ஹாதிம் ஆகியோர் இக்கருத்தை ஸுஃப்யான் அத்-தவ்ரீ வழியாக இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து பதிவு செய்துள்ளனர். அல்லாஹ்வின் கூற்றிற்கு இப்னு அப்பாஸ் (ரழி) அவர்கள் அளித்த விளக்கத்தை இப்னு அபீ ஹாதிம் பின்வருமாறு பதிவு செய்துள்ளார்:\n\r\n\n\r\nوَالَّذِينَ آمَنُوا وَاتَّبَعَتْهُمْ ذُرِّيَّتُهُم بِإِيمَانٍ أَلْحَقْنَا بِهِمْ ذُرِّيَّتَهُمْ\n\r\n\n\r\n(மேலும் எவர்கள் ஈமான் கொண்டு, அவர்களைப் பின்பற்றி அவர்களுடைய சந்ததியினரும் ஈமான் கொள்கிறார்களோ, அவர்களுடன் அவர்களுடைய சந்ததிகளை நாம் சேர்ப்போம்.) என்று கூறிவிட்டு, \"இவர்கள் ஈமானுடன் மரணித்த இறைநம்பிக்கையாளர்களின் சந்ததியினர் ஆவர். பெற்றோர்களின் அந்தஸ்து இவர்களின் அந்தஸ்தை விட உயர்வாக இருந்தால், அவர்கள் பெற்றோர்களுடன் சேர்த்து வைக்கப்படுவார்கள். இதற்காக பெற்றோர்கள் செய்த நற்செயல்களுக்குரிய கூலியில் எந்தக் குறைவும் செய்யப்படாது\" என்று விளக்கமளித்தார்கள். இமாம் அஹ்மதின் மகனான அப்துல்லாஹ் பதிவு செய்துள்ளதாவது: அலி (ரழி) அவர்கள் கூறினார்கள், \"கதீஜா (ரழி) அவர்கள் ஜாஹிலிய்யா (அறியாமை) காலத்தில் மரணித்த தனது இரு குழந்தைகளைப் பற்றி நபிகளாரிடம் கேட்டார்கள். அதற்கு அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள்:\n\r\n\n\r\n«هُمَا فِي النَّار»\n\r\n\n\r\n(அவ்விருவரும் நரக நெருப்பில் உள்ளனர்) என்று கூறினார்கள். கதீஜா (ரழி) அவர்களின் முகத்தில் சோகத்தைக் கண்டபோது, நபிகளார் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«لَوْ رَأَيْتِ مَكَانَهُمَا لَأَبْغَضْتِهِمَا»\n\r\n\n\r\n(அவர்கள் இருக்குமிடத்தை நீ பார்த்தால் அவர்களை நீ வெறுத்திருப்பாய்.) அதற்கு அவர், 'அல்லாஹ்வின் தூதரே! உங்களுடன் எனக்குப் பிறந்த குழந்தைகளின் நிலை என்ன?' என்று கேட்டார். அதற்கு நபிகளார் (ஸல்) அவர்கள்:\n\r\n\n\r\n«فِي الْجَنَّة»\n\r\n\n\r\n(அவர்கள் சுவர்க்கத்தில் உள்ளனர்) என்று கூறினார்கள். தொடர்ந்து அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«إِنَّ الْمُؤْمِنِينَ وَأَوْلَادَهُمْ فِي الْجَنَّةِ، وَإِنَّ الْمُشْرِكِينَ وَأَوْلَادَهُمْ فِي النَّار»\n\r\n\n\r\n(நிச்சயமாக இறைநம்பிக்கையாளர்களும் அவர்களின் சந்ததியினரும் சுவர்க்கத்தில் இருப்பார்கள்; இணைவைப்பாளர்களும் அவர்களின் சந்ததியினரும் நரக நெருப்பில் இருப்பார்கள்.) பின்னர் நபி (ஸல்) அவர்கள் இந்த வசனத்தை ஓதினார்கள்:\n\r\n\n\r\nوَالَّذِينَ آمَنُوا وَاتَّبَعَتْهُمْ ذُرِّيَّتُهُم بِإِيمَانٍ\n\r\n\n\r\n(மேலும் எவர்கள் ஈமான் கொண்டு, அவர்களைப் பின்பற்றி அவர்களுடைய சந்ததியினரும் ஈமான் கொள்கிறார்களோ...)\" பெற்றோர்களின் நற்செயல்களின் காரணமாக அல்லாஹ் பிள்ளைகளுக்கு இந்த பாக்கியத்தை வழங்குவது அவனது பேரருளும் கிருபையுமாகும். அதேபோல், பிள்ளைகள் பெற்றோர்களுக்காகப் பிரார்த்திப்பதன் காரணமாக, பெற்றோர்களுக்கும் அல்லாஹ் தனது அருளை வழங்குகிறான். அபூ ஹுரைரா (ரழி) அவர்கள் அறிவித்ததாக இமாம் அஹ்மத் பதிவு செய்துள்ளார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«إِنَّ اللهَ لَيَرْفَعُ الدَّرَجَةَ لِلْعَبْدِ الصَّالِحِ فِي الْجَنَّةِ فَيَقُولُ: يَا رَبِّ أَنَّى لِي هذِهِ؟ فَيَقُولُ: بِاسْتِغْفَارِ وَلَدِكَ لَك»\n\r\n\n\r\n(நிச்சயமாக அல்லாஹ் சுவர்க்கத்தில் ஒரு நல்லடியாரின் அந்தஸ்தை உயர்த்துகிறான். அப்போது அவர், \"என் இறைவா! இது எனக்கு எப்படி கிடைத்தது?\" என்று கேட்பார். அதற்கு அல்லாஹ், \"உனது பிள்ளை உனக்காகப் பாவமன்னிப்புத் தேடியதால்\" என்று பதிலளிப்பான்.) இந்த ஹதீஸின் அறிவிப்பாளர் தொடர் ஆதாரபூர்வமானது, ஆனால் இது ஸஹீஹ் நூல்களில் இந்த வடிவில் இடம்பெறவில்லை. எனினும், ஸஹீஹ் முஸ்லிமில் அபூ ஹுரைரா (ரழி) அவர்களின் அறிவிப்பில் இதற்குச் சான்றாக ஒரு ஹதீஸ் உள்ளது. அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«إِذَا مَاتَ ابْنُ آدَمَ انْقَطَعَ عَمَلُهُ إِلَّا مِنْ ثَلَاثٍ: صَدَقَةٍ جَارِيَةٍ، أَوْ عِلْمٍ يُنْتَفَعُ بِهِ، أَوْ وَلَدٍ صَالِحٍ يَدْعُو لَه»\n\r\n\n\r\n(ஆதமின் மகன் மரணிக்கும்போது, மூன்றைத் தவிர அவனது செயல்கள் யாவும் நின்றுவிடுகின்றன: அவை: நிலையான தர்மம், பிறர் பயனடையும் கல்வி மற்றும் அவனுக்காகப் பிரார்த்தனை செய்யும் ஒரு நல்ல பிள்ளை.)\n\r\n\n\r\nஅல்லாஹ் பாவிகளிடம் நீதியாக நடந்துகொள்கிறான்\n\r\n\n\r\nஉயர்ந்தோன் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nكُلُّ امْرِىءٍ بِمَا كَسَبَ رَهِينٌ\n\r\n\n\r\n(ஒவ்வொரு மனிதனும் தான் சம்பாதித்தவற்றுக்குப் பிணையாக இருக்கிறான்.) சந்ததியினரின் நற்செயல்கள் பெற்றோர்களின் நிலைக்குத் தகுதி பெறாவிட்டாலும், அவர்களை பெற்றோர்களின் அந்தஸ்துக்கு உயர்த்தும் தனது அருளைக் குறிப்பிட்ட பிறகு, மற்றவர்களின் தவறுகளுக்காக அல்லாஹ் யாரையும் தண்டிப்பதில்லை என்ற தனது நீதியை அவன் இங்கே உறுதிப்படுத்துகிறான்:\n\r\n\n\r\nكُلُّ امْرِىءٍ بِمَا كَسَبَ رَهِينٌ\n\r\n\n\r\n(ஒவ்வொரு மனிதனும் தான் சம்பாதித்தவற்றுக்குப் பிணையாக இருக்கிறான்.) எனவே, ஒவ்வொரு மனிதனும் தனது சொந்தச் செயல்களுக்குப் பொறுப்பாவான். மற்றவர்கள் செய்த பாவம், அது பெற்றோர்களோ அல்லது பிள்ளைகளோ செய்ததாக இருந்தாலும், ஒருவரது சுமையுடன் சேர்க்கப்படாது. இது பற்றி அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nكُلُّ نَفْسٍ بِمَا كَسَبَتْ رَهِينَةٌ - إِلاَّ أَصْحَابَ الْيَمِينِ - فِي جَنَّاتٍ يَتَسَاءَلُونَ - عَنِ الْمُجْرِمِينَ\n\r\n\n\r\n(ஒவ்வோர் ஆத்மாவும் தான் செய்தவற்றுக்குப் பிணையாகவே இருக்கும். வலப்புறத்தாரைத் தவிர. அவர்கள் சுவர்க்கச் சோலைகளில் இருந்துகொண்டு, குற்றவாளிகளைப் பற்றி விசாரிப்பார்கள்.) (74:38-41)\n\r\n\n\r\nசுவர்க்கத்தின் மது மற்றும் அங்கிருப்பவர்களின் இன்பங்கள் பற்றிய விவரிப்பு\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَأَمْدَدْنَاهُم بِفَاكِهَةٍ وَلَحْمٍ مِّمَّا يَشْتَهُونَ\n\r\n\n\r\n(மேலும், அவர்கள் விரும்பக்கூடிய பழங்களையும் இறைச்சியையும் அவர்களுக்கு நாம் தாராளமாக வழங்குவோம்.) அதாவது, அவர்கள் எதை ஆசைப்படுகிறார்களோ, எதை விரும்புகிறார்களோ அத்தகைய பலவிதமான பழங்களையும் இறைச்சிகளையும் நாம் அவர்களுக்கு வழங்குவோம்.\n\r\n\n\r\nيَتَنَازَعُونَ فِيهَا كَأْساً\n\r\n\n\r\n(அங்கே அவர்கள் ஒரு கோப்பையை ஒருவருக்கொருவர் கைமாற்றிக் கொள்வார்கள்.) அத்-தஹ்ஹாக் கூறுகிறார்கள், இதன் பொருள் 'மதுக் கோப்பை' என்பதாகும்.\n\r\n\n\r\nلاَّ لَغْوٌ فِيهَا وَلاَ تَأْثِيمٌ\n\r\n\n\r\n(அதில் வீணான பேச்சோ அல்லது பாவமான செயலோ இருக்காது.) அதாவது, அவர்கள் அதைப் பருகும்போது, இவ்வுலகக் குடிகாரர்களைப் போன்று வீணான வார்த்தைகளையோ அல்லது அசிங்கமான, பாவமான பேச்சுகளையோ பேசமாட்டார்கள். இப்னு அப்பாஸ் (ரழி) அவர்கள், 'லக்வ்' என்பது பொய்யையும், 'தஃதீம்' என்பது பொய் பேசுவதையும் குறிக்கும் என்கிறார்கள். முஜாஹித் கூறுகையில், \"அவர்கள் ஒருவரையொருவர் திட்ட மாட்டார்கள்; பாவம் செய்ய மாட்டார்கள்\" என்கிறார். கதாதா கூறுகையில், \"மதுவினால் இவ்வுலகில் ஏற்படும் தீய விளைவுகளில் ஷைத்தான் உதவி செய்கிறான். ஆனால், இவ்வுலக மதுவினால் ஏற்படும் தீமைகள் மற்றும் பாதிப்புகளிலிருந்து மறுமையின் மதுவை அல்லாஹ் தூய்மைப்படுத்தினான்\" என்கிறார். எனவே, தலைவலி, வயிற்றுவலி மற்றும் போதையை உண்டாக்கும் இவ்வுலக மதுவின் தன்மையிலிருந்து மறுமையின் மதுவை அல்லாஹ் பரிசுத்தமாக்கியுள்ளான். மறுமையின் மதுவைப் பருகுபவர்கள் எவ்விதப் பயனுமற்ற, முட்டாள்தனமான அல்லது தீய வார்த்தைகளைப் பேசமாட்டார்கள் என்று அல்லாஹ் கூறுகிறான். மேலும், மறுமையின் மது தோற்றத்தில் அழகாகவும், சுவையாகவும் இருக்கும் என்று அல்லாஹ் வர்ணிக்கிறான்:\n\r\n\n\r\nبَيْضَاءَ لَذَّةٍ لِلشَّارِبِينَ - لاَ فِيهَا غَوْلٌ وَلاَ هُمْ عَنْهَا يُنزَفُونَ\n\r\n\n\r\n(அது வெண்மையானது, அருந்துபவர்களுக்குச் சுவையானது. அதில் எவ்விதத் தீங்கும் இல்லை; அதனால் அவர்கள் போதை கொள்ளவும் மாட்டார்கள்.) (37:46-47). மேலும்,\n\r\n\n\r\nلاَّ يُصَدَّعُونَ عَنْهَا وَلاَ يُنزِفُونَ\n\r\n\n\r\n(அதனால் அவர்களுக்குத் தலைவலியோ அல்லது போதையோ ஏற்படாது.) (56:19). உயர்ந்தோன் அல்லாஹ் இங்கே கூறுகிறான்:\n\r\n\n\r\nيَتَنَازَعُونَ فِيهَا كَأْساً لاَّ لَغْوٌ فِيهَا وَلاَ تَأْثِيمٌ\n\r\n\n\r\n(அங்கே அவர்கள் ஒரு (மதுக்) கோப்பையை ஒருவருக்கொருவர் கைமாற்றிக் கொள்வார்கள்; அதில் வீண் பேச்சோ அல்லது பாவமோ இருக்காது.) அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَيَطُوفُ عَلَيْهِمْ غِلْمَانٌ لَّهُمْ كَأَنَّهُمْ لُؤْلُؤٌ مَّكْنُونٌ\n\r\n\n\r\n(மேலும், அவர்களுக்குப் பணிவிடை செய்வதற்காகப் பாதுகாக்கப்பட்ட முத்துக்களைப் போன்ற சிறுவர்கள் அவர்களைச் சுற்றி வருவார்கள்.) இது சுவர்க்கத்தில் இறைநம்பிக்கையாளர்களுக்குக் கிடைக்கும் உதவியாளர்களைப் பற்றிய விவரிப்பாகும். அச்சிறுவர்கள் பாதுகாக்கப்பட்ட முத்துக்களைப் போன்று அழகாகவும், நேர்த்தியாகவும், சுத்தமாகவும் இருப்பார்கள்.\n\r\n\n\r\nيَطُوفُ عَلَيْهِمْ وِلْدَانٌ مُّخَلَّدُونَ - بِأَكْوَابٍ وَأَبَارِيقَ وَكَأْسٍ مِّن مَّعِينٍ\n\r\n\n\r\n(என்றும் இளமையுடன் இருக்கும் சிறுவர்கள் கிண்ணங்களுடனும், ஜாடிகளுடனும், தெளிந்த மது நிறைந்த கோப்பையுடனும் அவர்களைச் சுற்றி வருவார்கள்.) (56:17-18) உயர்ந்தோன் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَأَقْبَلَ بَعْضُهُمْ عَلَى بَعْضٍ يَتَسَاءَلُونَ\n\r\n\n\r\n(மேலும் அவர்களில் ஒருவர் மற்றவரை முன்னோக்கி நலம் விசாரித்துக் கொள்வார்கள்.) அதாவது, இறைநம்பிக்கையாளர்கள் ஒருவருக்கொருவர் நெருங்கி, இவ்வுலகில் தாங்கள் செய்த செயல்களையும் தாங்கள் இருந்த நிலைகளையும் பற்றிப் பேசிக்கொள்வார்கள். இவ்வுலகில் மக்கள் ஒன்றுகூடி மது அருந்தும்போது, குறிப்பாகப் போதையில் பேசிக்கொள்வதைப் போன்று (ஆனால் பரிசுத்தமான முறையில்) உரையாடுவார்கள்.\n\r\n\n\r\nقَالُواْ إِنَّا كُنَّا قَبْلُ فِى أَهْلِنَا مُشْفِقِينَ\n\r\n\n\r\n(அவர்கள் கூறுவார்கள்: \"நிச்சயமாக நாம் இதற்கு முன்னால் நம் குடும்பத்தினரிடையே (அல்லாஹ்வைப் பற்றி) அஞ்சியவர்களாக இருந்தோம்.\") அதாவது, \"இவ்வுலக வாழ்க்கையில் நம் குடும்பத்தாருடன் இருந்தபோது நம் இறைவனைப் பற்றியும், அவனது வேதனை மற்றும் தண்டனையைப் பற்றியும் நாம் அஞ்சினோம்\" என்பதாகும்.\n\r\n\n\r\nفَمَنَّ اللَّهُ عَلَيْنَا وَوَقَانَا عَذَابَ السَّمُومِ\n\r\n\n\r\n(ஆகவே அல்லாஹ் நம் மீது பேரருள் புரிந்து, நச்சுக்காற்றின் (நரகின்) வேதனையிலிருந்து நம்மைக் காப்பாற்றினான்.) அதாவது, \"அவன் நமக்குக் கிருபை செய்து, நாம் எதைப் பயந்தோமோ அதிலிருந்து நம்மைக் காப்பாற்றினான்\" என்பதாகும்.\n\r\n\n\r\nإِنَّا كُنَّا مِن قَبْلُ نَدْعُوهُ\n\r\n\n\r\n(நிச்சயமாக நாம் இதற்கு முன்னரே அவனை அழைத்து (பிரார்த்தித்து) வந்தோம்.) அதாவது, \"பணிவுடனும் தாழ்மையுடனும் அவனிடம் நாம் பிரார்த்தனை செய்து வந்தோம். அவன் நம் பிரார்த்தனையை ஏற்று, நாம் விரும்பியதை நமக்கு வழங்கினான்.\"\n\r\n\n\r\nإِنَّهُ هُوَ الْبَرُّ الرَّحِيمُ\n\r\n\n\r\n(நிச்சயமாக அவன் மிக்க நன்மை செய்பவன்; மகா கருணையாளன்.) அதாவது, எமது பிரார்த்தனையை அவன் அங்கீகரித்தான்; எமது கோரிக்கையை ஏற்றான்; நாம் ஆதரவு வைத்திருந்ததை நமக்கு அளித்தான்."},"29":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=52&ayah=34\" class=\"link\">52:34</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 52:34 ஐ பார்க்கவும்"},"30":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=52&ayah=34\" class=\"link\">52:34</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 52:34 ஐ பார்க்கவும்"},"31":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=52&ayah=34\" class=\"link\">52:34</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 52:34 ஐ பார்க்கவும்"},"32":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=52&ayah=34\" class=\"link\">52:34</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 52:34 ஐ பார்க்கவும்"},"33":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=52&ayah=34\" class=\"link\">52:34</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 52:34 ஐ பார்க்கவும்"},"34":{"html":"<strong>நபி (ஸல்) அவர்கள் மீது இணைவைப்பாளர்கள் சுமத்திய பொய்யான குற்றச்சாட்டுகளிலிருந்து அவர்களைத் தூய்மைப்படுத்துதல்</strong><br />\r\n<br />\r\nமேலான அல்லாஹ், தனது செய்தியைத் தனது அடியார்களுக்கு எடுத்துரைக்குமாறும், தனக்கு இறக்கப்பட்ட வஹீயை (இறைச்செய்தியை) அவர்களுக்கு நினைவூட்டுமாறும் தனது தூதருக்குக் கட்டளையிடுகிறான். தொடர்ந்து, பொய்யர்களும் பாவிகளும் நபி (ஸல்) அவர்கள் மீது சுமத்திய பொய்யான குற்றச்சாட்டுகளை அல்லாஹ் மறுக்கிறான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَذَكِّرْ</span> <span class=\"quran-arabic-font text-success\">فَمَآ</span> <span class=\"quran-arabic-font text-success\">أَنتَ</span> <span class=\"quran-arabic-font text-success\">بِنِعْمَتِ</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ</span> <span class=\"quran-arabic-font text-success\">بِكَاهِنٍ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">مَجْنُونٍ</span><br />\r\n<br />\r\n(ஆகவே, நீர் நினைவூட்டுவீராக! உமது இறைவனின் அருளால் நீர் ஒரு குறிசொல்பவரோ (காஹின்) அல்லது பைத்தியக்காரரோ அல்லர்.) அல்லாஹ் கூறுகிறான், 'அல்லாஹ்வின் அருளால், முஹம்மதே! அறியாமையிலுள்ள குறைஷி இணைவைப்பாளர்கள் கூறுவது போல் நீர் ஒரு காஹின் அல்லர்.' காஹின் என்பவர், வானத்துச் செய்திகளை ஒட்டுக் கேட்கக்கூடிய ஜின்களிடமிருந்து தகவல்களைப் பெறும் குறிசொல்பவர் ஆவார்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">مَجْنُونٍ</span><br />\r\n<br />\r\n(பைத்தியக்காரரும் அல்லர்) - அதாவது ஷைத்தான் தீண்டியதால் பைத்தியம் பிடித்தவர் அல்லர். நபி (ஸல்) அவர்களைப் பற்றிப் பொய்யான கூற்றுகளைக் கூறிய இணைவைப்பாளர்களைக் கண்டித்து மேலான அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">يَقُولُونَ</span> <span class=\"quran-arabic-font text-success\">شَاعِرٌ</span> <span class=\"quran-arabic-font text-success\">نَّتَرَبَّصُ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">رَيْبَ</span> <span class=\"quran-arabic-font text-success\">الْمَنُونِ</span><br />\r\n<br />\r\n(அல்லது அவர்கள் கூறுகிறார்களா: \"இவர் ஒரு கவிஞர்! காலவோட்டத்தில் இவருக்கு ஏதேனும் ஒரு பேராபத்து ஏற்படுவதை நாங்கள் எதிர்பார்க்கிறோம்!\") அவர்கள் கூறினார்கள், 'அவருக்கு ஒரு பேரழிவு ஏற்படுவதை, உதாரணமாக மரணத்தை நாங்கள் எதிர்பார்க்கிறோம். மரணம் அவரைத் தழுவும் வரை நாங்கள் பொறுத்திருப்போம். இதன் மூலம் அவரது தொந்தரவிலிருந்தும் அவரது செய்தியிலிருந்தும் நாங்கள் விடுபடுவோம்.' மேலான அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُلْ</span> <span class=\"quran-arabic-font text-success\">تَرَبَّصُواْ</span> <span class=\"quran-arabic-font text-success\">فَإِنِّى</span> <span class=\"quran-arabic-font text-success\">مَعَكُمْ</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">الْمُتَرَبِّصِينَ</span><br />\r\n<br />\r\n(கூறுவீராக: \"நீங்கள் எதிர்பார்த்திருங்கள்! நிச்சயமாக நானும் உங்களுடன் எதிர்பார்த்திருப்பவர்களில் ஒருவனாக இருக்கிறேன்!\") 'நீங்கள் காத்திருங்கள், நானும் உங்களுடன் காத்திருக்கிறேன். இவ்வுலகிலும் மறுமையிலும் யாருக்கு நல்முடிவும் வெற்றியும் கிடைக்கும் என்பதை நீங்கள் விரைவில் அறிந்து கொள்வீர்கள்.' முஹம்மது பின் இஸ்ஹாக் அவர்கள், அப்துல்லாஹ் பின் அபீ நஜீஹ் அவர்கள் வழியாக முஜாஹித் அவர்கள் கூறியதாகப் பின்வருமாறு அறிவிக்கிறார்கள்; இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"குறைஷிகள் நபி (ஸல்) அவர்களின் விவகாரம் குறித்து விவாதிக்க 'தார் அந்-நத்வாவில்' (அவர்களது ஆலோசனைக் கூடத்தில்) கூடியபோது, அவர்களில் ஒருவன் கூறினான்: 'அவரைச் சங்கிலியால் பிணைத்துச் சிறையிலடையுங்கள். பிறகு காத்திருப்போம்; அவருக்கு முன்னிருந்த ஜுஹைர் மற்றும் அந்-நாபிகா போன்ற கவிஞர்களுக்கு ஏற்பட்டது போன்ற ஒரு மரணம் இவருக்கும் ஏற்படும் வரை காத்திருப்போம். ஏனெனில் இவரும் அவர்களைப் போன்ற ஒரு கவிஞர்தான்.' அவர்களின் இந்தக் கூற்றுக்குப் பதிலாக மேலான அல்லாஹ் பின்வருமாறு கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">يَقُولُونَ</span> <span class=\"quran-arabic-font text-success\">شَاعِرٌ</span> <span class=\"quran-arabic-font text-success\">نَّتَرَبَّصُ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">رَيْبَ</span> <span class=\"quran-arabic-font text-success\">الْمَنُونِ</span><br />\r\n<br />\r\n(அல்லது அவர்கள் கூறுகிறார்களா: \"இவர் ஒரு கவிஞர்! காலவோட்டத்தில் இவருக்கு ஏதேனும் ஒரு பேராபத்து ஏற்படுவதை நாங்கள் எதிர்பார்க்கிறோம்!\")\" மேலான அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">تَأْمُرُهُمْ</span> <span class=\"quran-arabic-font text-success\">أَحْلَامُهُم</span> <span class=\"quran-arabic-font text-success\">بِهَٰذَا</span><br />\r\n<br />\r\n(அல்லது அவர்களது அறிவாற்றல் (இவ்வாறு கூறும்படி) அவர்களுக்குக் கட்டளையிடுகிறதா?), அதாவது, \"முஹம்மதே! உமக்கு எதிராக இத்தகைய பொய்களைக் கூறுமாறு அவர்களது அறிவே கட்டளையிடுகிறதா? இவை உண்மையற்றவை மற்றும் பொய்யானவை என்பதை அவர்கள் உள்ளூர அறிந்திருந்த போதிலும் (இவ்வாறு கூறுகிறார்களே!)\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">هُمْ</span> <span class=\"quran-arabic-font text-success\">قَوْمٌ</span> <span class=\"quran-arabic-font text-success\">طَاغُونَ</span><br />\r\n<br />\r\n(அல்லது அவர்கள் வரம்பு மீறிய மக்களா?) \"நிச்சயமாக அவர்கள் வழிதவறியவர்கள், பிடிவாதக்காரர்கள் மற்றும் அநியாயக்காரர்கள். இதனால்தான் (முஹம்மதே!) உம்மைப் பற்றி இவ்வாறெல்லாம் அவர்கள் பேசுகிறார்கள்.\" மேலான அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">يَقُولُونَ</span> <span class=\"quran-arabic-font text-success\">تَقَوَّلَهُ</span><br />\r\n<br />\r\n(அல்லது அவர்கள் கூறுகிறார்களா: \"அவர் இதனை இட்டுக்கட்டிவிட்டார்\") அவர்கள் கூறினார்கள், 'அவர் இந்தக் குர்ஆனைத் தானாகவே கற்பனை செய்து இட்டுக்கட்டி கொண்டு வந்துள்ளார்.' இதற்கு மேலான அல்லாஹ் பின்வருமாறு பதிலளித்தான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بَل</span> <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">يُؤْمِنُونَ</span><br />\r\n<br />\r\n(இல்லை! அவர்கள் நம்பிக்கை கொள்ளவில்லை!), அதாவது, அவர்களது இறைநிராகரிப்பே இத்தகைய வார்த்தைகளைக் கூற அவர்களைத் தூண்டுகிறது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَلْيَأْتُواْ</span> <span class=\"quran-arabic-font text-success\">بِحَدِيثٍ</span> <span class=\"quran-arabic-font text-success\">مِّثْلِهِ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">صَادِقِينَ</span><br />\r\n<br />\r\n(அவர்கள் உண்மையாளர்களாக இருந்தால், இது போன்ற ஒரு செய்தியை அவர்களும் கொண்டு வரட்டும்.) அதாவது, முஹம்மது (ஸல்) அவர்கள் இந்தக் குர்ஆனைத் தாமாகவே இட்டுக்கட்டினார்கள் என்ற தங்கள் கூற்றில் அவர்கள் உண்மையாளர்களாக இருந்தால், இந்தக் குர்ஆனில் உள்ளதைப் போன்ற ஒன்றை அவர்களும் கொண்டு வரட்டும்! அவர்கள் பூமியில் உள்ள மனிதர்கள், ஜின்கள் என அனைவரது ஆற்றலையும் ஒன்றுதிரட்டி முயன்றாலும், இந்தக் குர்ஆனைப் போன்ற ஒன்றையோ, அல்லது இதில் உள்ளதைப் போன்ற பத்து அத்தியாயங்களையோ (ஸூராக்கள்), ஏன் ஒரே ஒரு அத்தியாயத்தையோ கூட அவர்களால் ஒருபோதும் கொண்டு வர முடியாது!<br />\r\n<br />","text":"நபி (ஸல்) அவர்கள் மீது இணைவைப்பாளர்கள் சுமத்திய பொய்யான குற்றச்சாட்டுகளிலிருந்து அவர்களைத் தூய்மைப்படுத்துதல்\n\r\n\n\r\nமேலான அல்லாஹ், தனது செய்தியைத் தனது அடியார்களுக்கு எடுத்துரைக்குமாறும், தனக்கு இறக்கப்பட்ட வஹீயை (இறைச்செய்தியை) அவர்களுக்கு நினைவூட்டுமாறும் தனது தூதருக்குக் கட்டளையிடுகிறான். தொடர்ந்து, பொய்யர்களும் பாவிகளும் நபி (ஸல்) அவர்கள் மீது சுமத்திய பொய்யான குற்றச்சாட்டுகளை அல்லாஹ் மறுக்கிறான்.\n\r\n\n\r\nفَذَكِّرْ فَمَآ أَنتَ بِنِعْمَتِ رَبِّكَ بِكَاهِنٍ وَلاَ مَجْنُونٍ\n\r\n\n\r\n(ஆகவே, நீர் நினைவூட்டுவீராக! உமது இறைவனின் அருளால் நீர் ஒரு குறிசொல்பவரோ (காஹின்) அல்லது பைத்தியக்காரரோ அல்லர்.) அல்லாஹ் கூறுகிறான், 'அல்லாஹ்வின் அருளால், முஹம்மதே! அறியாமையிலுள்ள குறைஷி இணைவைப்பாளர்கள் கூறுவது போல் நீர் ஒரு காஹின் அல்லர்.' காஹின் என்பவர், வானத்துச் செய்திகளை ஒட்டுக் கேட்கக்கூடிய ஜின்களிடமிருந்து தகவல்களைப் பெறும் குறிசொல்பவர் ஆவார்.\n\r\n\n\r\nوَلاَ مَجْنُونٍ\n\r\n\n\r\n(பைத்தியக்காரரும் அல்லர்) - அதாவது ஷைத்தான் தீண்டியதால் பைத்தியம் பிடித்தவர் அல்லர். நபி (ஸல்) அவர்களைப் பற்றிப் பொய்யான கூற்றுகளைக் கூறிய இணைவைப்பாளர்களைக் கண்டித்து மேலான அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nأَمْ يَقُولُونَ شَاعِرٌ نَّتَرَبَّصُ بِهِ رَيْبَ الْمَنُونِ\n\r\n\n\r\n(அல்லது அவர்கள் கூறுகிறார்களா: \"இவர் ஒரு கவிஞர்! காலவோட்டத்தில் இவருக்கு ஏதேனும் ஒரு பேராபத்து ஏற்படுவதை நாங்கள் எதிர்பார்க்கிறோம்!\") அவர்கள் கூறினார்கள், 'அவருக்கு ஒரு பேரழிவு ஏற்படுவதை, உதாரணமாக மரணத்தை நாங்கள் எதிர்பார்க்கிறோம். மரணம் அவரைத் தழுவும் வரை நாங்கள் பொறுத்திருப்போம். இதன் மூலம் அவரது தொந்தரவிலிருந்தும் அவரது செய்தியிலிருந்தும் நாங்கள் விடுபடுவோம்.' மேலான அல்லாஹ் கூறினான்:\n\r\n\n\r\nقُلْ تَرَبَّصُواْ فَإِنِّى مَعَكُمْ مِّنَ الْمُتَرَبِّصِينَ\n\r\n\n\r\n(கூறுவீராக: \"நீங்கள் எதிர்பார்த்திருங்கள்! நிச்சயமாக நானும் உங்களுடன் எதிர்பார்த்திருப்பவர்களில் ஒருவனாக இருக்கிறேன்!\") 'நீங்கள் காத்திருங்கள், நானும் உங்களுடன் காத்திருக்கிறேன். இவ்வுலகிலும் மறுமையிலும் யாருக்கு நல்முடிவும் வெற்றியும் கிடைக்கும் என்பதை நீங்கள் விரைவில் அறிந்து கொள்வீர்கள்.' முஹம்மது பின் இஸ்ஹாக் அவர்கள், அப்துல்லாஹ் பின் அபீ நஜீஹ் அவர்கள் வழியாக முஜாஹித் அவர்கள் கூறியதாகப் பின்வருமாறு அறிவிக்கிறார்கள்; இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"குறைஷிகள் நபி (ஸல்) அவர்களின் விவகாரம் குறித்து விவாதிக்க 'தார் அந்-நத்வாவில்' (அவர்களது ஆலோசனைக் கூடத்தில்) கூடியபோது, அவர்களில் ஒருவன் கூறினான்: 'அவரைச் சங்கிலியால் பிணைத்துச் சிறையிலடையுங்கள். பிறகு காத்திருப்போம்; அவருக்கு முன்னிருந்த ஜுஹைர் மற்றும் அந்-நாபிகா போன்ற கவிஞர்களுக்கு ஏற்பட்டது போன்ற ஒரு மரணம் இவருக்கும் ஏற்படும் வரை காத்திருப்போம். ஏனெனில் இவரும் அவர்களைப் போன்ற ஒரு கவிஞர்தான்.' அவர்களின் இந்தக் கூற்றுக்குப் பதிலாக மேலான அல்லாஹ் பின்வருமாறு கூறினான்:\n\r\n\n\r\nأَمْ يَقُولُونَ شَاعِرٌ نَّتَرَبَّصُ بِهِ رَيْبَ الْمَنُونِ\n\r\n\n\r\n(அல்லது அவர்கள் கூறுகிறார்களா: \"இவர் ஒரு கவிஞர்! காலவோட்டத்தில் இவருக்கு ஏதேனும் ஒரு பேராபத்து ஏற்படுவதை நாங்கள் எதிர்பார்க்கிறோம்!\")\" மேலான அல்லாஹ் கூறினான்:\n\r\n\n\r\nأَمْ تَأْمُرُهُمْ أَحْلَامُهُم بِهَٰذَا\n\r\n\n\r\n(அல்லது அவர்களது அறிவாற்றல் (இவ்வாறு கூறும்படி) அவர்களுக்குக் கட்டளையிடுகிறதா?), அதாவது, \"முஹம்மதே! உமக்கு எதிராக இத்தகைய பொய்களைக் கூறுமாறு அவர்களது அறிவே கட்டளையிடுகிறதா? இவை உண்மையற்றவை மற்றும் பொய்யானவை என்பதை அவர்கள் உள்ளூர அறிந்திருந்த போதிலும் (இவ்வாறு கூறுகிறார்களே!)\"\n\r\n\n\r\nأَمْ هُمْ قَوْمٌ طَاغُونَ\n\r\n\n\r\n(அல்லது அவர்கள் வரம்பு மீறிய மக்களா?) \"நிச்சயமாக அவர்கள் வழிதவறியவர்கள், பிடிவாதக்காரர்கள் மற்றும் அநியாயக்காரர்கள். இதனால்தான் (முஹம்மதே!) உம்மைப் பற்றி இவ்வாறெல்லாம் அவர்கள் பேசுகிறார்கள்.\" மேலான அல்லாஹ் கூறினான்:\n\r\n\n\r\nأَمْ يَقُولُونَ تَقَوَّلَهُ\n\r\n\n\r\n(அல்லது அவர்கள் கூறுகிறார்களா: \"அவர் இதனை இட்டுக்கட்டிவிட்டார்\") அவர்கள் கூறினார்கள், 'அவர் இந்தக் குர்ஆனைத் தானாகவே கற்பனை செய்து இட்டுக்கட்டி கொண்டு வந்துள்ளார்.' இதற்கு மேலான அல்லாஹ் பின்வருமாறு பதிலளித்தான்:\n\r\n\n\r\nبَل لاَّ يُؤْمِنُونَ\n\r\n\n\r\n(இல்லை! அவர்கள் நம்பிக்கை கொள்ளவில்லை!), அதாவது, அவர்களது இறைநிராகரிப்பே இத்தகைய வார்த்தைகளைக் கூற அவர்களைத் தூண்டுகிறது.\n\r\n\n\r\nفَلْيَأْتُواْ بِحَدِيثٍ مِّثْلِهِ إِن كَانُواْ صَادِقِينَ\n\r\n\n\r\n(அவர்கள் உண்மையாளர்களாக இருந்தால், இது போன்ற ஒரு செய்தியை அவர்களும் கொண்டு வரட்டும்.) அதாவது, முஹம்மது (ஸல்) அவர்கள் இந்தக் குர்ஆனைத் தாமாகவே இட்டுக்கட்டினார்கள் என்ற தங்கள் கூற்றில் அவர்கள் உண்மையாளர்களாக இருந்தால், இந்தக் குர்ஆனில் உள்ளதைப் போன்ற ஒன்றை அவர்களும் கொண்டு வரட்டும்! அவர்கள் பூமியில் உள்ள மனிதர்கள், ஜின்கள் என அனைவரது ஆற்றலையும் ஒன்றுதிரட்டி முயன்றாலும், இந்தக் குர்ஆனைப் போன்ற ஒன்றையோ, அல்லது இதில் உள்ளதைப் போன்ற பத்து அத்தியாயங்களையோ (ஸூராக்கள்), ஏன் ஒரே ஒரு அத்தியாயத்தையோ கூட அவர்களால் ஒருபோதும் கொண்டு வர முடியாது!"},"35":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=52&ayah=43\" class=\"link\">52:43</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 52:43 ஐ பார்க்கவும்"},"36":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=52&ayah=43\" class=\"link\">52:43</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 52:43 ஐ பார்க்கவும்"},"37":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=52&ayah=43\" class=\"link\">52:43</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 52:43 ஐ பார்க்கவும்"},"38":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=52&ayah=43\" class=\"link\">52:43</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 52:43 ஐ பார்க்கவும்"},"39":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=52&ayah=43\" class=\"link\">52:43</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 52:43 ஐ பார்க்கவும்"},"40":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=52&ayah=43\" class=\"link\">52:43</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 52:43 ஐ பார்க்கவும்"},"41":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=52&ayah=43\" class=\"link\">52:43</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 52:43 ஐ பார்க்கவும்"},"42":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=52&ayah=43\" class=\"link\">52:43</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 52:43 ஐ பார்க்கவும்"},"43":{"html":"<strong>தவ்ஹீதை (ஏகத்துவத்தை) உறுதிப்படுத்துவதும் இணைவைப்பாளர்களின் சூழ்ச்சிகளை முறியடிப்பதும். இது அல்லாஹ்வின் இரட்சகத்தன்மை மற்றும் வணக்கத்திற்குரியவன் என்ற தவ்ஹீதுகள் உறுதிப்படுத்தப்படும் இடமாகும்</strong><br />\r\n<br />\r\nஅல்லாஹ் கூறினான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">خُلِقُواْ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">غَيْرِ</span> <span class=\"quran-arabic-font text-success\">شَىْءٍ</span> <span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">هُمُ</span> <span class=\"quran-arabic-font text-success\">الْخَـلِقُونَ</span><br />\r\n<br />\r\n(அல்லது அவர்கள் எப்பொருளுமின்றி படைக்கப்பட்டார்களா? அல்லது அவர்களே படைப்பாளர்களா?) படைப்பவன் ஒருவன் இன்றி அவர்கள் படைக்கப்பட்டார்களா அல்லது அவர்கள் தங்களையே படைத்துக் கொண்டார்களா என்று அல்லாஹ் அவர்களைக் கேட்கிறான். இவை இரண்டுமே உண்மையில்லை. அவர்கள் ஒன்றுமில்லாதவர்களாக இருந்த நிலையில் அவர்களைப் படைத்து, அவர்களை இருப்புக்குக் கொண்டு வந்தவன் அல்லாஹ்வே ஆவான். ஜுபைர் பின் முத்இம் (ரழி) அவர்கள் கூறியதாவது: \"நபி (ஸல்) அவர்கள் மஃரிப் தொழுகையில் சூரத்துத் தூர் ஓதுவதை நான் கேட்டேன். அவர்கள் இந்த வசனத்தை எட்டியபோது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">خُلِقُواْ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">غَيْرِ</span> <span class=\"quran-arabic-font text-success\">شَىْءٍ</span> <span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">هُمُ</span> <span class=\"quran-arabic-font text-success\">الْخَـلِقُونَ</span> - <span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">خَلَقُواْ</span> <span class=\"quran-arabic-font text-success\">السَّمَـوَتِ</span> <span class=\"quran-arabic-font text-success\">وَالاٌّرْضَ</span> <span class=\"quran-arabic-font text-success\">بَل</span> <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">يُوقِنُونَ</span> - <span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">عِندَهُمْ</span> <span class=\"quran-arabic-font text-success\">خَزَآئِنُ</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ</span> <span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">هُمُ</span> <span class=\"quran-arabic-font text-success\">الْمُصَيْطِرُونَ</span><br />\r\n<br />\r\n(அல்லது அவர்கள் எப்பொருளுமின்றி படைக்கப்பட்டார்களா? அல்லது அவர்களே படைப்பாளர்களா? அல்லது அவர்கள் வானங்களையும் பூமியையும் படைத்தார்களா? இல்லை, அவர்கள் உறுதியான நம்பிக்கை கொள்ளாதவர்களாகவே உள்ளனர். அல்லது உமது இறைவனின் கருவூலங்கள் அவர்களிடமிருக்கின்றனவா? அல்லது அவர்கள் ஆதிக்கம் செலுத்துபவர்களா?), என் இதயம் பறந்து விடுவதைப்போல் இருந்தது.\" இந்த ஹதீஸ் பல்வேறு அறிவிப்பாளர் தொடர்கள் வழியாக ஸஹீஹைன் (புகாரி மற்றும் முஸ்லிம்) ஆகிய இரண்டிலும் இடம்பெற்றுள்ளது. பத்ர் போருக்குப் பிறகு பிடிபட்ட கைதிகளுக்காகப் பிணைத் தொகை செலுத்த ஜுபைர் பின் முத்இம் (ரழி) அவர்கள் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் வந்தார்கள். அந்த நேரத்தில் அவர்கள் ஓர் இணைவைப்பாளராகவே இருந்தார்கள். நபி (ஸல்) அவர்கள் இந்த வசனத்தை ஓதியதைக் கேட்டதே அவர்கள் பின்னர் இஸ்லாத்தைத் தழுவ ஒரு முக்கிய காரணமாக அமைந்தது.<br />\r\n<br />\r\nஅல்லாஹ் கூறினான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">خَلَقُواْ</span> <span class=\"quran-arabic-font text-success\">السَّمَـوَتِ</span> <span class=\"quran-arabic-font text-success\">وَالاٌّرْضَ</span> <span class=\"quran-arabic-font text-success\">بَل</span> <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">يُوقِنُونَ</span><br />\r\n<br />\r\n(அல்லது அவர்கள் வானங்களையும் பூமியையும் படைத்தார்களா? இல்லை, அவர்கள் உறுதியாக நம்புவதில்லை.) அதாவது, இணைவைப்பாளர்கள் வானங்களையும் பூமியையும் தாங்களே படைத்தார்களா என்று கேட்டு, அல்லாஹ் அவர்களின் இணைவைப்பைக் கண்டிக்கிறான். அல்லாஹ் மட்டுமே தனக்கு எவ்வித கூட்டாளியும் இன்றிப் படைப்பவன் என்பதை அவர்கள் அறிந்தே இருந்தனர். இருப்பினும், உறுதியான நம்பிக்கை (யகீன்) இல்லாத காரணத்தால் அவர்கள் இணைவைப்பில் வீழ்ந்தனர்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">عِندَهُمْ</span> <span class=\"quran-arabic-font text-success\">خَزَآئِنُ</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ</span> <span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">هُمُ</span> <span class=\"quran-arabic-font text-success\">الْمُصَيْطِرُونَ</span><br />\r\n<br />\r\n(அல்லது உமது இறைவனின் கருவூலங்கள் அவர்களிடமிருக்கின்றனவா? அல்லது அவர்கள் ஆதிக்கம் செலுத்துபவர்களா?) அதாவது, அல்லாஹ்வின் ஆட்சியில் அவர்கள் நாடியதைச் செய்வதற்கு அவர்களுக்கு அதிகாரம் உள்ளதா? அவனது அருட்கருவூலங்களின் சாவிகள் அவர்கள் கைகளில் உள்ளனவா?<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">هُمُ</span> <span class=\"quran-arabic-font text-success\">الْمُصَيْطِرُونَ</span><br />\r\n<br />\r\n(அல்லது அவர்கள் ஆதிக்கம் செலுத்துபவர்களா?) அதாவது, படைப்பினங்களைக் கணக்குக் கேட்கும் அளவுக்கு அவர்கள் அதிகாரம் படைத்தவர்களா? ஒருபோதும் இல்லை! கண்ணியமும் உயர்வும் மிக்க அல்லாஹ் மட்டுமே அகிலத்தின் ஒரே அரசனும் உரிமையாளனும் ஆவான்; அவன் நாடியதைச் செய்கிறான்.<br />\r\n<br />\r\nஅல்லாஹ் கூறினான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">سُلَّمٌ</span> <span class=\"quran-arabic-font text-success\">يَسْتَمِعُونَ</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span><br />\r\n<br />\r\n(அல்லது அவர்களுக்கு ஓர் ஏணி இருக்கிறதா? அதன் வழியாக அவர்கள் (வானவர்களின் உரையாடல்களைச்) செவியுறுகின்றார்களா?) அதாவது, அவர்கள் வானத்திற்கு (வானவர்கள் இருக்கும் இடத்திற்கு) செல்வதற்கு ஏதேனும் ஏணி வைத்துள்ளார்களா?<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَلْيَأْتِ</span> <span class=\"quran-arabic-font text-success\">مُسْتَمِعُهُم</span> <span class=\"quran-arabic-font text-success\">بِسُلْطَـنٍ</span> <span class=\"quran-arabic-font text-success\">مُّبِينٍ</span><br />\r\n<br />\r\n(அவ்வாறாயின், அவர்களில் செவியுற்றவர் தெளிவான ஆதாரத்தைக் கொண்டு வரட்டும்.) அதாவது, அவர்களது செயல்களுக்கும் கூற்றுகளுக்கும் ஆதரவாக அந்தச் செவியுற்றவர் தெளிவான ஆதாரத்தை முன்வைக்கட்டும். அவர்களால் ஒருபோதும் அதனைச் செய்ய முடியாது. எனவே, அவர்களிடம் எதுவுமில்லை; அவர்களது நிலைப்பாட்டிற்கு எவ்வித சான்றும் இல்லை. அல்லாஹ்வுக்குப் பெண் பிள்ளைகள் உள்ளனர் என்றும் வானவர்கள் பெண் பாலார் என்றும் அவர்கள் வாதிடுவதை அல்லாஹ் கண்டிக்கிறான்! அந்த இணைவைப்பாளர்கள் தங்களுக்கு ஆண் குழந்தைகளையே தேர்ந்தெடுத்துக் கொண்டனர்; பெண் குழந்தைகளை விட அவர்களுக்கே முன்னுரிமை அளித்தனர். அவர்களில் ஒருவனுக்குப் பெண் குழந்தை பிறந்துவிட்டதாக நற்செய்தி கூறப்பட்டால், அவனது கோபத்தினால் முகம் கறுத்துவிடும்! இவ்வாறிருக்க, அவர்கள் வானவர்களை அல்லாஹ்வின் பெண் பிள்ளைகளாகக் கருதி, அல்லாஹ்வை விடுத்து அவர்களை வணங்கினர்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">الْبَنَـتُ</span> <span class=\"quran-arabic-font text-success\">وَلَكُمُ</span> <span class=\"quran-arabic-font text-success\">الْبَنُونَ</span><br />\r\n<br />\r\n(அல்லது அவனுக்குப் பெண் பிள்ளைகளும் உங்களுக்கு ஆண் பிள்ளைகளுமா?) அல்லாஹ் இந்த வசனத்தில் அவர்களுக்கு மிகக் கடுமையான எச்சரிக்கையையும் கண்டனத்தையும் விடுக்கிறான்.<br />\r\n<br />\r\nஅல்லாஹ் கூறினான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">تَسْـَلُهُمْ</span> <span class=\"quran-arabic-font text-success\">أَجْراً</span><br />\r\n<br />\r\n(அல்லது நீர் அவர்களிடமிருந்து கூலி எதையும் கேட்கிறீரா?) அதாவது, 'அல்லாஹ்வின் செய்தியை அவர்களுக்குப் போதிப்பதற்காக நீர் ஏதேனும் கைமாறு கேட்கிறீரா? இல்லை, நீர் அவர்களிடம் எந்தக் கூலியையும் கேட்கவில்லை.'<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَهُم</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">مَّغْرَمٍ</span> <span class=\"quran-arabic-font text-success\">مُّثْقَلُونَ</span><br />\r\n<br />\r\n(அதனால் அவர்கள் கடன் சுமையினால் பாரமாக்கப்பட்டுள்ளார்களா?) அதாவது, நீர் அவர்களிடம் கூலி எதையும் கேட்காத நிலையில், (இஸ்லாத்தை ஏற்பது) அவர்களுக்குப் பெரும் சுமையாக இருக்கிறதா? இல்லை.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">عِندَهُمُ</span> <span class=\"quran-arabic-font text-success\">الْغَيْبُ</span> <span class=\"quran-arabic-font text-success\">فَهُمْ</span> <span class=\"quran-arabic-font text-success\">يَكْتُبُونَ</span><br />\r\n<br />\r\n(அல்லது மறைவானவை அவர்களிடம் இருந்து, அதை அவர்கள் எழுதிக் கொண்டிருக்கின்றார்களா?) அதாவது, அவர்களிடம் மறைவானவற்றைப் பற்றிய அறிவு இல்லை. ஏனெனில், வானங்களிலோ பூமியிலோ அல்லாஹ்வைத் தவிர எவரும் மறைவானவற்றை அறிய முடியாது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">يُرِيدُونَ</span> <span class=\"quran-arabic-font text-success\">كَيْداً</span> <span class=\"quran-arabic-font text-success\">فَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُواْ</span> <span class=\"quran-arabic-font text-success\">هُمُ</span> <span class=\"quran-arabic-font text-success\">الْمَكِيدُونَ</span><br />\r\n<br />\r\n(அல்லது அவர்கள் ஏதேனும் சூழ்ச்சி செய்ய நாடுகின்றார்களா? ஆனால், நிராகரிப்பவர்களே சூழ்ச்சிக்கு உள்ளாவார்கள்!) அல்லாஹ் கேட்கிறான்: 'தூதர் (ஸல்) அவர்களையும் அவர்களது மார்க்கத்தையும் பற்றி இவ்வாறெல்லாம் பேசும் இந்த மக்கள், மக்களை ஏமாற்றவும் தூதர் (ஸல்) அவர்களுக்கும் அவரது தோழர்களுக்கும் (ரழி) எதிராகச் சூழ்ச்சி செய்யவும் நாடுகிறார்களா? அவ்வாறு செய்தால், அவர்களது சூழ்ச்சிகள் அவர்களுக்கே வினையாக முடியும் என்பதை அவர்கள் அறிந்து கொள்ளட்டும். எனவே, அவர்கள் சூழ்ச்சி செய்பவர்கள் அல்ல, மாறாகச் சூழ்ச்சிக்கு உள்ளாக்கப்படுபவர்கள்!'<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">إِلَـهٌ</span> <span class=\"quran-arabic-font text-success\">غَيْرُ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">سُبْحَـنَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">عَمَّا</span> <span class=\"quran-arabic-font text-success\">يُشْرِكُونَ</span><br />\r\n<br />\r\n(அல்லது அவர்களுக்கு அல்லாஹ்வைத் தவிர வேறு ஏதேனும் கடவுள் இருக்கிறதா? அவர்கள் இணைவைப்பவற்றை விட்டும் அல்லாஹ் மகா தூய்மையானவன்.) சிலைகளை வணங்குவதற்கும், அல்லாஹ்வுக்கு இணையாகப் பிற தெய்வங்களை அழைப்பதற்கும் எதிராக இணைவைப்பாளர்களுக்கு விடுக்கப்படும் கடுமையான மறுப்பு இந்த வசனத்தில் உள்ளது. பின்னர், அவர்கள் கற்பனை செய்யும் இணைகள், அவர்களது பொய்கள் மற்றும் இணைவைப்பிலிருந்து கண்ணியமிக்க தனது சுயத்தைத் தூய்மைப்படுத்துகிறான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">سُبْحَـنَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">عَمَّا</span> <span class=\"quran-arabic-font text-success\">يُشْرِكُونَ</span><br />\r\n<br />\r\n(அவர்கள் இணைவைப்பவற்றை விட்டும் அல்லாஹ் மகா தூய்மையானவன்.)<br />\r\n<br />\r\n<br />\r\n<br />","text":"தவ்ஹீதை (ஏகத்துவத்தை) உறுதிப்படுத்துவதும் இணைவைப்பாளர்களின் சூழ்ச்சிகளை முறியடிப்பதும். இது அல்லாஹ்வின் இரட்சகத்தன்மை மற்றும் வணக்கத்திற்குரியவன் என்ற தவ்ஹீதுகள் உறுதிப்படுத்தப்படும் இடமாகும்\n\r\n\n\r\nஅல்லாஹ் கூறினான்,\n\r\n\n\r\nأَمْ خُلِقُواْ مِنْ غَيْرِ شَىْءٍ أَمْ هُمُ الْخَـلِقُونَ\n\r\n\n\r\n(அல்லது அவர்கள் எப்பொருளுமின்றி படைக்கப்பட்டார்களா? அல்லது அவர்களே படைப்பாளர்களா?) படைப்பவன் ஒருவன் இன்றி அவர்கள் படைக்கப்பட்டார்களா அல்லது அவர்கள் தங்களையே படைத்துக் கொண்டார்களா என்று அல்லாஹ் அவர்களைக் கேட்கிறான். இவை இரண்டுமே உண்மையில்லை. அவர்கள் ஒன்றுமில்லாதவர்களாக இருந்த நிலையில் அவர்களைப் படைத்து, அவர்களை இருப்புக்குக் கொண்டு வந்தவன் அல்லாஹ்வே ஆவான். ஜுபைர் பின் முத்இம் (ரழி) அவர்கள் கூறியதாவது: \"நபி (ஸல்) அவர்கள் மஃரிப் தொழுகையில் சூரத்துத் தூர் ஓதுவதை நான் கேட்டேன். அவர்கள் இந்த வசனத்தை எட்டியபோது:\n\r\n\n\r\nأَمْ خُلِقُواْ مِنْ غَيْرِ شَىْءٍ أَمْ هُمُ الْخَـلِقُونَ - أَمْ خَلَقُواْ السَّمَـوَتِ وَالاٌّرْضَ بَل لاَّ يُوقِنُونَ - أَمْ عِندَهُمْ خَزَآئِنُ رَبِّكَ أَمْ هُمُ الْمُصَيْطِرُونَ\n\r\n\n\r\n(அல்லது அவர்கள் எப்பொருளுமின்றி படைக்கப்பட்டார்களா? அல்லது அவர்களே படைப்பாளர்களா? அல்லது அவர்கள் வானங்களையும் பூமியையும் படைத்தார்களா? இல்லை, அவர்கள் உறுதியான நம்பிக்கை கொள்ளாதவர்களாகவே உள்ளனர். அல்லது உமது இறைவனின் கருவூலங்கள் அவர்களிடமிருக்கின்றனவா? அல்லது அவர்கள் ஆதிக்கம் செலுத்துபவர்களா?), என் இதயம் பறந்து விடுவதைப்போல் இருந்தது.\" இந்த ஹதீஸ் பல்வேறு அறிவிப்பாளர் தொடர்கள் வழியாக ஸஹீஹைன் (புகாரி மற்றும் முஸ்லிம்) ஆகிய இரண்டிலும் இடம்பெற்றுள்ளது. பத்ர் போருக்குப் பிறகு பிடிபட்ட கைதிகளுக்காகப் பிணைத் தொகை செலுத்த ஜுபைர் பின் முத்இம் (ரழி) அவர்கள் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் வந்தார்கள். அந்த நேரத்தில் அவர்கள் ஓர் இணைவைப்பாளராகவே இருந்தார்கள். நபி (ஸல்) அவர்கள் இந்த வசனத்தை ஓதியதைக் கேட்டதே அவர்கள் பின்னர் இஸ்லாத்தைத் தழுவ ஒரு முக்கிய காரணமாக அமைந்தது.\n\r\n\n\r\nஅல்லாஹ் கூறினான்,\n\r\n\n\r\nأَمْ خَلَقُواْ السَّمَـوَتِ وَالاٌّرْضَ بَل لاَّ يُوقِنُونَ\n\r\n\n\r\n(அல்லது அவர்கள் வானங்களையும் பூமியையும் படைத்தார்களா? இல்லை, அவர்கள் உறுதியாக நம்புவதில்லை.) அதாவது, இணைவைப்பாளர்கள் வானங்களையும் பூமியையும் தாங்களே படைத்தார்களா என்று கேட்டு, அல்லாஹ் அவர்களின் இணைவைப்பைக் கண்டிக்கிறான். அல்லாஹ் மட்டுமே தனக்கு எவ்வித கூட்டாளியும் இன்றிப் படைப்பவன் என்பதை அவர்கள் அறிந்தே இருந்தனர். இருப்பினும், உறுதியான நம்பிக்கை (யகீன்) இல்லாத காரணத்தால் அவர்கள் இணைவைப்பில் வீழ்ந்தனர்.\n\r\n\n\r\nأَمْ عِندَهُمْ خَزَآئِنُ رَبِّكَ أَمْ هُمُ الْمُصَيْطِرُونَ\n\r\n\n\r\n(அல்லது உமது இறைவனின் கருவூலங்கள் அவர்களிடமிருக்கின்றனவா? அல்லது அவர்கள் ஆதிக்கம் செலுத்துபவர்களா?) அதாவது, அல்லாஹ்வின் ஆட்சியில் அவர்கள் நாடியதைச் செய்வதற்கு அவர்களுக்கு அதிகாரம் உள்ளதா? அவனது அருட்கருவூலங்களின் சாவிகள் அவர்கள் கைகளில் உள்ளனவா?\n\r\n\n\r\nأَمْ هُمُ الْمُصَيْطِرُونَ\n\r\n\n\r\n(அல்லது அவர்கள் ஆதிக்கம் செலுத்துபவர்களா?) அதாவது, படைப்பினங்களைக் கணக்குக் கேட்கும் அளவுக்கு அவர்கள் அதிகாரம் படைத்தவர்களா? ஒருபோதும் இல்லை! கண்ணியமும் உயர்வும் மிக்க அல்லாஹ் மட்டுமே அகிலத்தின் ஒரே அரசனும் உரிமையாளனும் ஆவான்; அவன் நாடியதைச் செய்கிறான்.\n\r\n\n\r\nஅல்லாஹ் கூறினான்,\n\r\n\n\r\nأَمْ لَهُمْ سُلَّمٌ يَسْتَمِعُونَ فِيهِ\n\r\n\n\r\n(அல்லது அவர்களுக்கு ஓர் ஏணி இருக்கிறதா? அதன் வழியாக அவர்கள் (வானவர்களின் உரையாடல்களைச்) செவியுறுகின்றார்களா?) அதாவது, அவர்கள் வானத்திற்கு (வானவர்கள் இருக்கும் இடத்திற்கு) செல்வதற்கு ஏதேனும் ஏணி வைத்துள்ளார்களா?\n\r\n\n\r\nفَلْيَأْتِ مُسْتَمِعُهُم بِسُلْطَـنٍ مُّبِينٍ\n\r\n\n\r\n(அவ்வாறாயின், அவர்களில் செவியுற்றவர் தெளிவான ஆதாரத்தைக் கொண்டு வரட்டும்.) அதாவது, அவர்களது செயல்களுக்கும் கூற்றுகளுக்கும் ஆதரவாக அந்தச் செவியுற்றவர் தெளிவான ஆதாரத்தை முன்வைக்கட்டும். அவர்களால் ஒருபோதும் அதனைச் செய்ய முடியாது. எனவே, அவர்களிடம் எதுவுமில்லை; அவர்களது நிலைப்பாட்டிற்கு எவ்வித சான்றும் இல்லை. அல்லாஹ்வுக்குப் பெண் பிள்ளைகள் உள்ளனர் என்றும் வானவர்கள் பெண் பாலார் என்றும் அவர்கள் வாதிடுவதை அல்லாஹ் கண்டிக்கிறான்! அந்த இணைவைப்பாளர்கள் தங்களுக்கு ஆண் குழந்தைகளையே தேர்ந்தெடுத்துக் கொண்டனர்; பெண் குழந்தைகளை விட அவர்களுக்கே முன்னுரிமை அளித்தனர். அவர்களில் ஒருவனுக்குப் பெண் குழந்தை பிறந்துவிட்டதாக நற்செய்தி கூறப்பட்டால், அவனது கோபத்தினால் முகம் கறுத்துவிடும்! இவ்வாறிருக்க, அவர்கள் வானவர்களை அல்லாஹ்வின் பெண் பிள்ளைகளாகக் கருதி, அல்லாஹ்வை விடுத்து அவர்களை வணங்கினர்.\n\r\n\n\r\nأَمْ لَهُ الْبَنَـتُ وَلَكُمُ الْبَنُونَ\n\r\n\n\r\n(அல்லது அவனுக்குப் பெண் பிள்ளைகளும் உங்களுக்கு ஆண் பிள்ளைகளுமா?) அல்லாஹ் இந்த வசனத்தில் அவர்களுக்கு மிகக் கடுமையான எச்சரிக்கையையும் கண்டனத்தையும் விடுக்கிறான்.\n\r\n\n\r\nஅல்லாஹ் கூறினான்,\n\r\n\n\r\nأَمْ تَسْـَلُهُمْ أَجْراً\n\r\n\n\r\n(அல்லது நீர் அவர்களிடமிருந்து கூலி எதையும் கேட்கிறீரா?) அதாவது, 'அல்லாஹ்வின் செய்தியை அவர்களுக்குப் போதிப்பதற்காக நீர் ஏதேனும் கைமாறு கேட்கிறீரா? இல்லை, நீர் அவர்களிடம் எந்தக் கூலியையும் கேட்கவில்லை.'\n\r\n\n\r\nفَهُم مِّن مَّغْرَمٍ مُّثْقَلُونَ\n\r\n\n\r\n(அதனால் அவர்கள் கடன் சுமையினால் பாரமாக்கப்பட்டுள்ளார்களா?) அதாவது, நீர் அவர்களிடம் கூலி எதையும் கேட்காத நிலையில், (இஸ்லாத்தை ஏற்பது) அவர்களுக்குப் பெரும் சுமையாக இருக்கிறதா? இல்லை.\n\r\n\n\r\nأَمْ عِندَهُمُ الْغَيْبُ فَهُمْ يَكْتُبُونَ\n\r\n\n\r\n(அல்லது மறைவானவை அவர்களிடம் இருந்து, அதை அவர்கள் எழுதிக் கொண்டிருக்கின்றார்களா?) அதாவது, அவர்களிடம் மறைவானவற்றைப் பற்றிய அறிவு இல்லை. ஏனெனில், வானங்களிலோ பூமியிலோ அல்லாஹ்வைத் தவிர எவரும் மறைவானவற்றை அறிய முடியாது.\n\r\n\n\r\nأَمْ يُرِيدُونَ كَيْداً فَالَّذِينَ كَفَرُواْ هُمُ الْمَكِيدُونَ\n\r\n\n\r\n(அல்லது அவர்கள் ஏதேனும் சூழ்ச்சி செய்ய நாடுகின்றார்களா? ஆனால், நிராகரிப்பவர்களே சூழ்ச்சிக்கு உள்ளாவார்கள்!) அல்லாஹ் கேட்கிறான்: 'தூதர் (ஸல்) அவர்களையும் அவர்களது மார்க்கத்தையும் பற்றி இவ்வாறெல்லாம் பேசும் இந்த மக்கள், மக்களை ஏமாற்றவும் தூதர் (ஸல்) அவர்களுக்கும் அவரது தோழர்களுக்கும் (ரழி) எதிராகச் சூழ்ச்சி செய்யவும் நாடுகிறார்களா? அவ்வாறு செய்தால், அவர்களது சூழ்ச்சிகள் அவர்களுக்கே வினையாக முடியும் என்பதை அவர்கள் அறிந்து கொள்ளட்டும். எனவே, அவர்கள் சூழ்ச்சி செய்பவர்கள் அல்ல, மாறாகச் சூழ்ச்சிக்கு உள்ளாக்கப்படுபவர்கள்!'\n\r\n\n\r\nأَمْ لَهُمْ إِلَـهٌ غَيْرُ اللَّهِ سُبْحَـنَ اللَّهِ عَمَّا يُشْرِكُونَ\n\r\n\n\r\n(அல்லது அவர்களுக்கு அல்லாஹ்வைத் தவிர வேறு ஏதேனும் கடவுள் இருக்கிறதா? அவர்கள் இணைவைப்பவற்றை விட்டும் அல்லாஹ் மகா தூய்மையானவன்.) சிலைகளை வணங்குவதற்கும், அல்லாஹ்வுக்கு இணையாகப் பிற தெய்வங்களை அழைப்பதற்கும் எதிராக இணைவைப்பாளர்களுக்கு விடுக்கப்படும் கடுமையான மறுப்பு இந்த வசனத்தில் உள்ளது. பின்னர், அவர்கள் கற்பனை செய்யும் இணைகள், அவர்களது பொய்கள் மற்றும் இணைவைப்பிலிருந்து கண்ணியமிக்க தனது சுயத்தைத் தூய்மைப்படுத்துகிறான்.\n\r\n\n\r\nسُبْحَـنَ اللَّهِ عَمَّا يُشْرِكُونَ\n\r\n\n\r\n(அவர்கள் இணைவைப்பவற்றை விட்டும் அல்லாஹ் மகா தூய்மையானவன்.)"},"44":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=52&ayah=49\" class=\"link\">52:49</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 52:49 ஐ பார்க்கவும்"},"45":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=52&ayah=49\" class=\"link\">52:49</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 52:49 ஐ பார்க்கவும்"},"46":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=52&ayah=49\" class=\"link\">52:49</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 52:49 ஐ பார்க்கவும்"},"47":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=52&ayah=49\" class=\"link\">52:49</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 52:49 ஐ பார்க்கவும்"},"48":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=52&ayah=49\" class=\"link\">52:49</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 52:49 ஐ பார்க்கவும்"},"49":{"html":"<strong>இணைவைப்பாளர்களின் பிடிவாதமும், அவர்களின் தண்டனையும்</strong><br />\r\n<br />\r\nமேலான அல்லாஹ், இணைவைப்பாளர்களின் பிடிவாதத்தையும் அவர்களைச் சுற்றி நடப்பவை குறித்த அவர்களின் அறியாமையையும் மீண்டும் உறுதிப்படுத்துகிறான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِن</span> <span class=\"quran-arabic-font text-success\">يَرَوْاْ</span> <span class=\"quran-arabic-font text-success\">كِسْفاً</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">السَّمَآءِ</span> <span class=\"quran-arabic-font text-success\">سَاقِطاً</span><br />\r\n<br />\r\n(வானத்திலிருந்து ஒரு துண்டு கீழே விழுவதை அவர்கள் கண்டாலும்,) அதாவது அவர்களுக்குத் தண்டனையாக அது விழுந்தாலும், அது தங்களை நோக்கி வருவதை அவர்கள் நம்ப மாட்டார்கள். மாறாக, இவை ஒன்றன் மேல் ஒன்றாக அடுக்கப்பட்ட மேகங்கள் என்று அவர்கள் கூறுவார்கள். மேலான அல்லாஹ் மற்றோர் ஆயத்தில் (வசனத்தில்) கூறினான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَوْ</span> <span class=\"quran-arabic-font text-success\">فَتَحْنَا</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِم</span> <span class=\"quran-arabic-font text-success\">بَاباً</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">السَّمَاءِ</span> <span class=\"quran-arabic-font text-success\">فَظَلُّواْ</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span> <span class=\"quran-arabic-font text-success\">يَعْرُجُونَ</span> - <span class=\"quran-arabic-font text-success\">لَقَالُواْ</span> <span class=\"quran-arabic-font text-success\">إِنَّمَا</span> <span class=\"quran-arabic-font text-success\">سُكِّرَتْ</span> <span class=\"quran-arabic-font text-success\">أَبْصَـرُنَا</span> <span class=\"quran-arabic-font text-success\">بَلْ</span> <span class=\"quran-arabic-font text-success\">نَحْنُ</span> <span class=\"quran-arabic-font text-success\">قَوْمٌ</span> <span class=\"quran-arabic-font text-success\">مَّسْحُورُونَ</span><br />\r\n<br />\r\n(நாம் அவர்களுக்கு வானத்திலிருந்து ஒரு வாசலைத் திறந்து, அதன் வழியாக அவர்கள் (பகலில்) ஏறிக்கொண்டே இருந்தாலும், அவர்கள் நிச்சயமாகக் கூறுவார்கள்: \"எங்கள் பார்வைகள் மழுங்கடிக்கப்பட்டுவிட்டன. இல்லை, நாங்கள் சூனியம் செய்யப்பட்ட ஒரு சமூகத்தினர்.\") (<a href=\"qurandisp.php?sura=15&ayah=14\" class=\"link\">15:14</a>-15) மேலான அல்லாஹ் கூறினான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَذَرْهُمْ</span><br />\r\n<br />\r\n(எனவே அவர்களை விட்டுவிடுவீராக), \"முஹம்மதே (ஸல்)!\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">يُلَـقُواْ</span> <span class=\"quran-arabic-font text-success\">يَوْمَهُمُ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span> <span class=\"quran-arabic-font text-success\">يُصْعَقُونَ</span><br />\r\n<br />\r\n(அவர்கள் மூர்ச்சையடைந்து விழும் அந்நாளை அவர்கள் சந்திக்கும் வரை.) இது மறுமை நாளைக் குறிக்கும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يُغْنِى</span> <span class=\"quran-arabic-font text-success\">عَنْهُمْ</span> <span class=\"quran-arabic-font text-success\">كَيْدُهُمْ</span> <span class=\"quran-arabic-font text-success\">شَيْئاً</span><br />\r\n<br />\r\n(அந்நாளில் அவர்களுடைய சூழ்ச்சி அவர்களுக்கு எந்தப் பயனும் தராது,) அதாவது, மறுமை நாளில், இவ்வுலக வாழ்வில் அவர்கள் திட்டமிட்ட ஏமாற்று வேலைகளும் சூழ்ச்சிகளும் அவர்களுக்குச் சிறிதளவும் உதவாது,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">هُمْ</span> <span class=\"quran-arabic-font text-success\">يُنصَرُونَ</span><br />\r\n<br />\r\n(அவர்களுக்கு உதவியும் செய்யப்படமாட்டாது.) மேலான அல்லாஹ் கூறினான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِنَّ</span> <span class=\"quran-arabic-font text-success\">لِلَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ظَلَمُواْ</span> <span class=\"quran-arabic-font text-success\">عَذَاباً</span> <span class=\"quran-arabic-font text-success\">دُونَ</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span><br />\r\n<br />\r\n(நிச்சயமாக, அநீதி இழைப்பவர்களுக்கு, இதற்கு முன்பாக மற்றொரு வேதனையும் இருக்கிறது;) அதாவது இவ்வுலகில் அவர்கள் அனுபவிக்கும் வேதனை. மேலான அல்லாஹ் மற்றொரு ஆயத்தில் கூறினான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَنُذِيقَنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">الْعَذَابِ</span> <span class=\"quran-arabic-font text-success\">الاٌّدْنَى</span> <span class=\"quran-arabic-font text-success\">دُونَ</span> <span class=\"quran-arabic-font text-success\">الْعَذَابِ</span> <span class=\"quran-arabic-font text-success\">الاٌّكْبَرِ</span> <span class=\"quran-arabic-font text-success\">لَعَلَّهُمْ</span> <span class=\"quran-arabic-font text-success\">يَرْجِعُونَ</span><br />\r\n<br />\r\n(நிச்சயமாக, அவர்கள் (பாவங்களிலிருந்து) திரும்புவதற்காக, மாபெரும் வேதனைக்கு (மறுமைக்கு) முன்னதாக, சமீபத்திய (இவ்வுலக) வேதனையை நாம் அவர்களைச் சுவைக்கச் செய்வோம்.) (<a href=\"qurandisp.php?sura=32&ayah=21\" class=\"link\">32:21</a>) அல்லாஹ் கூறினான்;<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَـكِنَّ</span> <span class=\"quran-arabic-font text-success\">أَكْثَرَهُمْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَعْلَمُونَ</span><br />\r\n<br />\r\n(ஆனால் அவர்களில் பெரும்பாலோர் அறியமாட்டார்கள்.) அதாவது, 'அவர்கள் திருந்தித் தவ்பா (மனந்திரும்புதல்) செய்வதற்காக இவ்வுலக வாழ்வில் நாம் அவர்களை வேதனைப்படுத்துவோம், பல்வேறு சோதனைகளைக் கொண்டு அவர்களைச் சோதிப்போம். இருப்பினும், தங்களுக்கு என்ன நடக்கிறது அல்லது ஏன் நடக்கிறது என்பதை அவர்கள் உணர்வதில்லை. ஏனெனில், அந்த வேதனை நீக்கப்பட்டதும், தாங்கள் முன்பு செய்து கொண்டிருந்த மிக மோசமான செயல்களுக்கே அவர்கள் மீண்டும் திரும்பிவிடுகிறார்கள்.' என்று ஒரு ஹதீஸில் கூறப்பட்டுள்ளது.<br />\r\n<br />\r\n<strong>பொறுமை காக்குமாறும் அல்லாஹ்வைத் துதிக்குமாறும் நபிக்குக் கட்டளையிடுதல்</strong><br />\r\n<br />\r\nமேலான அல்லாஹ் கூறினான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَاصْبِرْ</span> <span class=\"quran-arabic-font text-success\">لِحُكْمِ</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ</span> <span class=\"quran-arabic-font text-success\">فَإِنَّكَ</span> <span class=\"quran-arabic-font text-success\">بِأَعْيُنِنَا</span><br />\r\n<br />\r\n(எனவே, உமது இறைவனின் தீர்ப்புக்காகப் பொறுமையுடன் காத்திருப்பீராக! நிச்சயமாக நீர் நம்முடைய கண்காணிப்பில் இருக்கிறீர்;) அதாவது, 'அவர்களின் தொந்தரவுகளைப் பொறுத்துக் கொள்வீராக, அதைப் பற்றிக் கவலைப்பட வேண்டாம். ஏனெனில் நீர் எமது கண்காணிப்பிலும் பாதுகாப்பிலும் இருக்கிறீர். நிச்சயமாக நாம் உமக்குப் பாதுகாப்பு அளிப்போம்.'<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَسَبِّحْ</span> <span class=\"quran-arabic-font text-success\">بِحَمْدِ</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ</span> <span class=\"quran-arabic-font text-success\">حِينَ</span> <span class=\"quran-arabic-font text-success\">تَقُومُ</span><br />\r\n<br />\r\n(நீர் எழும்போது உமது இறைவனின் புகழைக் கொண்டு அவனைத் துதிப்பீராக.) அத்-தஹ்ஹாக் அவர்கள் கூறினார்கள், \"அதாவது தொழுகைக்காக நிலை கொள்ளும்போது (இவ்வாறு) கூறுவதாகும்: 'யா அல்லாஹ்! நீ தூய்மையானவன், உன்னைப் புகழ்கிறேன். உனது பெயர் மிகவும் அருள்மிக்கது, உனது மேன்மை உயர்ந்தது. உன்னைத் தவிர வணக்கத்திற்குரிய இறைவன் வேறு எவரும் இல்லை'.\" இமாம் முஸ்லிம் அவர்கள் தனது ஸஹீஹ் நூலில், உமர் (ரழி) அவர்கள் தொழுகையைத் தொடங்கும்போது இந்தத் துஆவை ஓதுவார்கள் என்று பதிவு செய்துள்ளார்கள். இமாம் அஹ்மத் மற்றும் ஸுனன் நூலாசிரியர்கள் இந்த ஹதீஸை அபூ ஸயீத் (ரழி) மற்றும் பிற ஸஹாபாக்களிடமிருந்து (ரழி) பதிவு செய்துள்ளார்கள். நபி (ஸல்) அவர்கள் இவ்வாறு ஓதுபவர்களாக இருந்தார்கள் என்று அவர்கள் குறிப்பிட்டார்கள். அபுல் ஜவ்ஸா அவர்கள் இந்த ஆயத்தைப் பற்றி விளக்கமளிக்கும்போது;<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَسَبِّحْ</span> <span class=\"quran-arabic-font text-success\">بِحَمْدِ</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ</span> <span class=\"quran-arabic-font text-success\">حِينَ</span> <span class=\"quran-arabic-font text-success\">تَقُومُ</span><br />\r\n<br />\r\n(நீர் எழும்போது உமது இறைவனின் புகழைக் கொண்டு அவனைத் துதிப்பீராக.) \"நீர் உமது தூக்கத்திலிருந்து, உமது படுக்கையிலிருந்து எழும்போது\" என்று கூறினார்கள். இதுவே இப்னு ஜரீர் அவர்கள் தேர்ந்தெடுத்த கருத்தாகும். இமாம் அஹ்மத் அவர்கள் பதிவு செய்துள்ள ஹதீஸும் இந்தக் கருத்தை ஆதரிக்கிறது. அதில் உபாதா பின் அஸ்-ஸாமித் (ரழி) அவர்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் பின்வருமாறு கூறினார்கள் என்று அறிவித்துள்ளார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">تَعَارَّ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">اللَّيْلِ</span> <span class=\"quran-arabic-font text-success\">فَقَالَ</span>: <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">إِلهَ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">وَحْدَهُ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">شَرِيكَ</span> <span class=\"quran-arabic-font text-success\">لَهُ،</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">الْمُلْكُ</span> <span class=\"quran-arabic-font text-success\">وَلَهُ</span> <span class=\"quran-arabic-font text-success\">الْحَمْدُ،</span> <span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">كُلِّ</span> <span class=\"quran-arabic-font text-success\">شَيْءٍ</span> <span class=\"quran-arabic-font text-success\">قَدِيرٌ،</span> <span class=\"quran-arabic-font text-success\">سُبْحَانَ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">وَالْحَمْدُ</span> <span class=\"quran-arabic-font text-success\">للهِ</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">إِلهَ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">وَاللهُ</span> <span class=\"quran-arabic-font text-success\">أَكْبَرُ،</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">حَوْلَ</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">قُوَّةَ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">بِاللهِ</span>. <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">قَالَ</span>: <span class=\"quran-arabic-font text-success\">رَبِّ</span> <span class=\"quran-arabic-font text-success\">اغْفِرْ</span> <span class=\"quran-arabic-font text-success\">لِي</span> <span class=\"quran-arabic-font text-success\">أو</span> <span class=\"quran-arabic-font text-success\">قال</span>: <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">دَعَا</span> <span class=\"quran-arabic-font text-success\">اسْتُجِيبَ</span> <span class=\"quran-arabic-font text-success\">لَهُ،</span> <span class=\"quran-arabic-font text-success\">فَإِنْ</span> <span class=\"quran-arabic-font text-success\">عَزَمَ</span> <span class=\"quran-arabic-font text-success\">فَتَوَضَّأَ</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">صَلَّى،</span> <span class=\"quran-arabic-font text-success\">قُبِلَتْ</span> <span class=\"quran-arabic-font text-success\">صَلَاتُه</span>»<br />\r\n<br />\r\n(யார் இரவில் விழித்து, 'லா இலாஹ இல்லல்லாஹு வஹ்தஹு லா ஷரீக்க லஹு, லஹுல் முல்கு வலஹுல் ஹம்து, வஹுவ அலா குல்லி ஷையின் கதீர். ஸுப்ஹானல்லாஹி, வல்ஹம்துலில்லாஹி, வலா இலாஹ இல்லல்லாஹு, வல்லாஹு அக்பர். வலா ஹவ்ல வலா குவ்வத்த இல்லா பில்லாஹ்' என்று கூறி, பின்னர் 'இறைவா! என்னை மன்னிப்பாயாக' என்றோ அல்லது வேறு ஏதேனும் துஆவோ செய்தால், அவரது துஆ ஏற்கப்படும். அவர் உறுதியுடன் உளூச் செய்து தொழுதால், அவரது தொழுகையும் அங்கீகரிக்கப்படும்.) புகாரி மற்றும் ஸுனன் நூலாசிரியர்களும் இந்த ஹதீஸைப் பதிவு செய்துள்ளனர். இப்னு அபீ நஜீஹ் அவர்கள் வழியாக முஜாஹித் அவர்கள் இந்த ஆயத்திற்கு விளக்கமளிக்கும்போது,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَسَبِّحْ</span> <span class=\"quran-arabic-font text-success\">بِحَمْدِ</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ</span> <span class=\"quran-arabic-font text-success\">حِينَ</span> <span class=\"quran-arabic-font text-success\">تَقُومُ</span><br />\r\n<br />\r\n(நீர் எழும்போது உமது இறைவனின் புகழைக் கொண்டு அவனைத் துதிப்பீராக.) என்று கூறிவிட்டு, \"நீர் அமர்ந்திருக்கும் ஒவ்வொரு சபையிலிருந்து எழும்போதும்\" என்று கூறினார்கள். அத்-தவ்ரீ அவர்கள், அபூ இஸ்ஹாக் வழியாக அபூ அஹ்வஸ் அவர்கள் கூறியதாகக் குறிப்பிடுகிறார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَسَبِّحْ</span> <span class=\"quran-arabic-font text-success\">بِحَمْدِ</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ</span> <span class=\"quran-arabic-font text-success\">حِينَ</span> <span class=\"quran-arabic-font text-success\">تَقُومُ</span><br />\r\n<br />\r\n(நீர் எழும்போது உமது இறைவனின் புகழைக் கொண்டு அவனைத் துதிப்பீராக.) \"ஒருவர் ஒரு சபையிலிருந்து எழும்போது, 'யா அல்லாஹ்! நீ தூய்மையானவன், உன்னைப் புகழ்கிறேன்' என்று கூற வேண்டும்.\" அபூ ஹுரைரா (ரழி) அவர்கள், நபி (ஸல்) அவர்கள் பின்வருமாறு கூறினார்கள் என்று அறிவிக்கிறார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">جَلَسَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">مَجْلِسٍ</span> <span class=\"quran-arabic-font text-success\">فَكَثُرَ</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span> <span class=\"quran-arabic-font text-success\">لَغَطُهُ،</span> <span class=\"quran-arabic-font text-success\">فَقَالَ</span> <span class=\"quran-arabic-font text-success\">قَبْلَ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">يَقُومَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">مَجْلِسِهِ</span>: <span class=\"quran-arabic-font text-success\">سُبْحَانَكَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُمَّ</span> <span class=\"quran-arabic-font text-success\">وَبِحَمْدِكَ،</span> <span class=\"quran-arabic-font text-success\">أَشْهَدُ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">إِلهَ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">أَنْتَ،</span> <span class=\"quran-arabic-font text-success\">أَسْتَغْفِرُكَ</span> <span class=\"quran-arabic-font text-success\">وَأَتُوبُ</span> <span class=\"quran-arabic-font text-success\">إِلَيْكَ،</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">غَفَرَ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">مَجْلِسِهِ</span> <span class=\"quran-arabic-font text-success\">ذلِك</span>»<br />\r\n<br />\r\n(யார் ஒரு சபையில் அமர்ந்து, அதில் வீணான பேச்சுகளை அதிகமாகப் பேசிவிட்டு, அந்தச் சபையிலிருந்து எழுவதற்கு முன்பாக, 'ஸுப்ஹானகல்லாஹும்ம வபிஹம்திக, அஷ்ஹது அன் லா இலாஹ இல்லா அன்த, அஸ்தஃபிருக வஅதூபு இலைக்' என்று கூறுகிறாரோ, அந்தச் சபையில் அவர் பேசிய வீணான பேச்சுகளை அல்லாஹ் மன்னித்துவிடுவான்.) இதனை திர்மிதீ அவர்கள் பதிவு செய்துள்ளார்கள், இது அவருடைய வாசகமாகும். மேலும் நஸயீ அவர்கள் 'அமல் அல்-யவ்ம் வல்-லைலா' என்ற நூலிலும் இதைப் பதிவு செய்துள்ளார்கள். திர்மிதீ அவர்கள் இது \"ஹஸன் ஸஹீஹ்\" என்று கூறியுள்ளார். இமாம் ஹாகிம் அவர்களும் தனது முஸ்தத்ரக் நூலில் இதைப் பதிவு செய்து, \"இதன் அறிவிப்பாளர் தொடர் முஸ்லிமின் நிபந்தனைகளுக்கு உட்பட்டது\" என்று குறிப்பிட்டுள்ளார். மேலான அல்லாஹ் கூறினான்;<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمِنَ</span> <span class=\"quran-arabic-font text-success\">الَّيْلِ</span> <span class=\"quran-arabic-font text-success\">فَسَبِّحْهُ</span><br />\r\n<br />\r\n(மேலும் இரவிலும் அவனைத் துதிப்பீராக), அதாவது குர்ஆன் ஓதுவதன் மூலமும், இரவுத் தொழுகை மூலமும் அல்லாஹ்வை நினைவு கூர்ந்து வணங்குங்கள். மேலான அல்லாஹ் மற்றொரு ஆயத்தில் கூறினான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمِنَ</span> <span class=\"quran-arabic-font text-success\">الَّيْلِ</span> <span class=\"quran-arabic-font text-success\">فَتَهَجَّدْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">نَافِلَةً</span> <span class=\"quran-arabic-font text-success\">لَّكَ</span> <span class=\"quran-arabic-font text-success\">عَسَى</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يَبْعَثَكَ</span> <span class=\"quran-arabic-font text-success\">رَبُّكَ</span> <span class=\"quran-arabic-font text-success\">مَقَاماً</span> <span class=\"quran-arabic-font text-success\">مَّحْمُودًا</span><br />\r\n<br />\r\n(மேலும் இரவின் ஒரு பகுதியில் தஹஜ்ஜுத் தொழுவீராக! இது உமக்கு உபரியான வணக்கமாகும். இதன் மூலம் உமது இறைவன் உம்மை மகாமன் மஹ்மூத் (புகழத்தக்க இடம்) எனும் நிலையில் எழுப்பக்கூடும்.) (<a href=\"qurandisp.php?sura=17&ayah=79\" class=\"link\">17:79</a>) அல்லாஹ் கூறினான்;<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِدْبَارَ</span> <span class=\"quran-arabic-font text-success\">النُّجُومِ</span><br />\r\n<br />\r\n(நட்சத்திரங்கள் மறையும் நேரத்திலும்.) இப்னு அப்பாஸ் (ரழி) அவர்களின் அறிவிப்பின்படி, இது ஃபஜ்ர் தொழுகைக்கு முன்னால் தொழப்படும் இரண்டு ரக்அத் சுன்னத் தொழுகையைக் குறிக்கும். இந்த இரண்டு ரக்அத்களும் நட்சத்திரங்கள் மறையத் தொடங்கும் முன் செய்யப்படும் ஒரு உறுதிப்படுத்தப்பட்ட ஸுன்னத் ஆகும். ஆயிஷா (ரழி) அவர்கள் கூறியதாக 'ஸஹீஹைன்' நூல்களில் இவ்வாறு இடம்பெற்றுள்ளது: \"நபி (ஸல்) அவர்கள் ஃபஜ்ருடைய இரண்டு (ஸுன்னத்) ரக்அத்களைப் போல வேறெந்த உபரியான தொழுகையையும் இவ்வளவு பேணுதலாகத் தொழுததில்லை.\" முஸ்லிமில் இடம்பெற்றுள்ள மற்றோர் அறிவிப்பில் நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">رَكْعَتَا</span> <span class=\"quran-arabic-font text-success\">الْفَجْرِ</span> <span class=\"quran-arabic-font text-success\">خَيْرٌ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span>»<br />\r\n<br />\r\n(ஃபஜ்ருடைய இரண்டு (ஸுன்னத்) ரக்அத்கள் இவ்வுலகையும் அதிலுள்ள அனைத்தையும் விடச் சிறந்ததாகும்.)<br />\r\n<br />\r\nஇத்துடன் ஸூரதுத் தூரின் தஃப்ஸீர் நிறைவுற்றது. எல்லாப் புகழும் நன்றியும் அல்லாஹ்வுக்கே உரியது.<br />\r\n<br />\r\n<br />\r\n<br />","text":"இணைவைப்பாளர்களின் பிடிவாதமும், அவர்களின் தண்டனையும்\n\r\n\n\r\nமேலான அல்லாஹ், இணைவைப்பாளர்களின் பிடிவாதத்தையும் அவர்களைச் சுற்றி நடப்பவை குறித்த அவர்களின் அறியாமையையும் மீண்டும் உறுதிப்படுத்துகிறான்,\n\r\n\n\r\nوَإِن يَرَوْاْ كِسْفاً مِّنَ السَّمَآءِ سَاقِطاً\n\r\n\n\r\n(வானத்திலிருந்து ஒரு துண்டு கீழே விழுவதை அவர்கள் கண்டாலும்,) அதாவது அவர்களுக்குத் தண்டனையாக அது விழுந்தாலும், அது தங்களை நோக்கி வருவதை அவர்கள் நம்ப மாட்டார்கள். மாறாக, இவை ஒன்றன் மேல் ஒன்றாக அடுக்கப்பட்ட மேகங்கள் என்று அவர்கள் கூறுவார்கள். மேலான அல்லாஹ் மற்றோர் ஆயத்தில் (வசனத்தில்) கூறினான்,\n\r\n\n\r\nوَلَوْ فَتَحْنَا عَلَيْهِم بَاباً مِّنَ السَّمَاءِ فَظَلُّواْ فِيهِ يَعْرُجُونَ - لَقَالُواْ إِنَّمَا سُكِّرَتْ أَبْصَـرُنَا بَلْ نَحْنُ قَوْمٌ مَّسْحُورُونَ\n\r\n\n\r\n(நாம் அவர்களுக்கு வானத்திலிருந்து ஒரு வாசலைத் திறந்து, அதன் வழியாக அவர்கள் (பகலில்) ஏறிக்கொண்டே இருந்தாலும், அவர்கள் நிச்சயமாகக் கூறுவார்கள்: \"எங்கள் பார்வைகள் மழுங்கடிக்கப்பட்டுவிட்டன. இல்லை, நாங்கள் சூனியம் செய்யப்பட்ட ஒரு சமூகத்தினர்.\") (15:14-15) மேலான அல்லாஹ் கூறினான்,\n\r\n\n\r\nفَذَرْهُمْ\n\r\n\n\r\n(எனவே அவர்களை விட்டுவிடுவீராக), \"முஹம்மதே (ஸல்)!\"\n\r\n\n\r\nحَتَّى يُلَـقُواْ يَوْمَهُمُ الَّذِى فِيهِ يُصْعَقُونَ\n\r\n\n\r\n(அவர்கள் மூர்ச்சையடைந்து விழும் அந்நாளை அவர்கள் சந்திக்கும் வரை.) இது மறுமை நாளைக் குறிக்கும்.\n\r\n\n\r\nيَوْمَ لاَ يُغْنِى عَنْهُمْ كَيْدُهُمْ شَيْئاً\n\r\n\n\r\n(அந்நாளில் அவர்களுடைய சூழ்ச்சி அவர்களுக்கு எந்தப் பயனும் தராது,) அதாவது, மறுமை நாளில், இவ்வுலக வாழ்வில் அவர்கள் திட்டமிட்ட ஏமாற்று வேலைகளும் சூழ்ச்சிகளும் அவர்களுக்குச் சிறிதளவும் உதவாது,\n\r\n\n\r\nوَلاَ هُمْ يُنصَرُونَ\n\r\n\n\r\n(அவர்களுக்கு உதவியும் செய்யப்படமாட்டாது.) மேலான அல்லாஹ் கூறினான்,\n\r\n\n\r\nوَإِنَّ لِلَّذِينَ ظَلَمُواْ عَذَاباً دُونَ ذَلِكَ\n\r\n\n\r\n(நிச்சயமாக, அநீதி இழைப்பவர்களுக்கு, இதற்கு முன்பாக மற்றொரு வேதனையும் இருக்கிறது;) அதாவது இவ்வுலகில் அவர்கள் அனுபவிக்கும் வேதனை. மேலான அல்லாஹ் மற்றொரு ஆயத்தில் கூறினான்,\n\r\n\n\r\nوَلَنُذِيقَنَّهُمْ مِّنَ الْعَذَابِ الاٌّدْنَى دُونَ الْعَذَابِ الاٌّكْبَرِ لَعَلَّهُمْ يَرْجِعُونَ\n\r\n\n\r\n(நிச்சயமாக, அவர்கள் (பாவங்களிலிருந்து) திரும்புவதற்காக, மாபெரும் வேதனைக்கு (மறுமைக்கு) முன்னதாக, சமீபத்திய (இவ்வுலக) வேதனையை நாம் அவர்களைச் சுவைக்கச் செய்வோம்.) (32:21) அல்லாஹ் கூறினான்;\n\r\n\n\r\nوَلَـكِنَّ أَكْثَرَهُمْ لاَ يَعْلَمُونَ\n\r\n\n\r\n(ஆனால் அவர்களில் பெரும்பாலோர் அறியமாட்டார்கள்.) அதாவது, 'அவர்கள் திருந்தித் தவ்பா (மனந்திரும்புதல்) செய்வதற்காக இவ்வுலக வாழ்வில் நாம் அவர்களை வேதனைப்படுத்துவோம், பல்வேறு சோதனைகளைக் கொண்டு அவர்களைச் சோதிப்போம். இருப்பினும், தங்களுக்கு என்ன நடக்கிறது அல்லது ஏன் நடக்கிறது என்பதை அவர்கள் உணர்வதில்லை. ஏனெனில், அந்த வேதனை நீக்கப்பட்டதும், தாங்கள் முன்பு செய்து கொண்டிருந்த மிக மோசமான செயல்களுக்கே அவர்கள் மீண்டும் திரும்பிவிடுகிறார்கள்.' என்று ஒரு ஹதீஸில் கூறப்பட்டுள்ளது.\n\r\n\n\r\nபொறுமை காக்குமாறும் அல்லாஹ்வைத் துதிக்குமாறும் நபிக்குக் கட்டளையிடுதல்\n\r\n\n\r\nமேலான அல்லாஹ் கூறினான்,\n\r\n\n\r\nوَاصْبِرْ لِحُكْمِ رَبِّكَ فَإِنَّكَ بِأَعْيُنِنَا\n\r\n\n\r\n(எனவே, உமது இறைவனின் தீர்ப்புக்காகப் பொறுமையுடன் காத்திருப்பீராக! நிச்சயமாக நீர் நம்முடைய கண்காணிப்பில் இருக்கிறீர்;) அதாவது, 'அவர்களின் தொந்தரவுகளைப் பொறுத்துக் கொள்வீராக, அதைப் பற்றிக் கவலைப்பட வேண்டாம். ஏனெனில் நீர் எமது கண்காணிப்பிலும் பாதுகாப்பிலும் இருக்கிறீர். நிச்சயமாக நாம் உமக்குப் பாதுகாப்பு அளிப்போம்.'\n\r\n\n\r\nوَسَبِّحْ بِحَمْدِ رَبِّكَ حِينَ تَقُومُ\n\r\n\n\r\n(நீர் எழும்போது உமது இறைவனின் புகழைக் கொண்டு அவனைத் துதிப்பீராக.) அத்-தஹ்ஹாக் அவர்கள் கூறினார்கள், \"அதாவது தொழுகைக்காக நிலை கொள்ளும்போது (இவ்வாறு) கூறுவதாகும்: 'யா அல்லாஹ்! நீ தூய்மையானவன், உன்னைப் புகழ்கிறேன். உனது பெயர் மிகவும் அருள்மிக்கது, உனது மேன்மை உயர்ந்தது. உன்னைத் தவிர வணக்கத்திற்குரிய இறைவன் வேறு எவரும் இல்லை'.\" இமாம் முஸ்லிம் அவர்கள் தனது ஸஹீஹ் நூலில், உமர் (ரழி) அவர்கள் தொழுகையைத் தொடங்கும்போது இந்தத் துஆவை ஓதுவார்கள் என்று பதிவு செய்துள்ளார்கள். இமாம் அஹ்மத் மற்றும் ஸுனன் நூலாசிரியர்கள் இந்த ஹதீஸை அபூ ஸயீத் (ரழி) மற்றும் பிற ஸஹாபாக்களிடமிருந்து (ரழி) பதிவு செய்துள்ளார்கள். நபி (ஸல்) அவர்கள் இவ்வாறு ஓதுபவர்களாக இருந்தார்கள் என்று அவர்கள் குறிப்பிட்டார்கள். அபுல் ஜவ்ஸா அவர்கள் இந்த ஆயத்தைப் பற்றி விளக்கமளிக்கும்போது;\n\r\n\n\r\nوَسَبِّحْ بِحَمْدِ رَبِّكَ حِينَ تَقُومُ\n\r\n\n\r\n(நீர் எழும்போது உமது இறைவனின் புகழைக் கொண்டு அவனைத் துதிப்பீராக.) \"நீர் உமது தூக்கத்திலிருந்து, உமது படுக்கையிலிருந்து எழும்போது\" என்று கூறினார்கள். இதுவே இப்னு ஜரீர் அவர்கள் தேர்ந்தெடுத்த கருத்தாகும். இமாம் அஹ்மத் அவர்கள் பதிவு செய்துள்ள ஹதீஸும் இந்தக் கருத்தை ஆதரிக்கிறது. அதில் உபாதா பின் அஸ்-ஸாமித் (ரழி) அவர்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் பின்வருமாறு கூறினார்கள் என்று அறிவித்துள்ளார்கள்:\n\r\n\n\r\n«مَنْ تَعَارَّ مِنَ اللَّيْلِ فَقَالَ: لَا إِلهَ إِلَّا اللهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، سُبْحَانَ اللهِ وَالْحَمْدُ للهِ وَلَا إِلهَ إِلَّا اللهُ وَاللهُ أَكْبَرُ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللهِ. ثُمَّ قَالَ: رَبِّ اغْفِرْ لِي أو قال: ثُمَّ دَعَا اسْتُجِيبَ لَهُ، فَإِنْ عَزَمَ فَتَوَضَّأَ ثُمَّ صَلَّى، قُبِلَتْ صَلَاتُه»\n\r\n\n\r\n(யார் இரவில் விழித்து, 'லா இலாஹ இல்லல்லாஹு வஹ்தஹு லா ஷரீக்க லஹு, லஹுல் முல்கு வலஹுல் ஹம்து, வஹுவ அலா குல்லி ஷையின் கதீர். ஸுப்ஹானல்லாஹி, வல்ஹம்துலில்லாஹி, வலா இலாஹ இல்லல்லாஹு, வல்லாஹு அக்பர். வலா ஹவ்ல வலா குவ்வத்த இல்லா பில்லாஹ்' என்று கூறி, பின்னர் 'இறைவா! என்னை மன்னிப்பாயாக' என்றோ அல்லது வேறு ஏதேனும் துஆவோ செய்தால், அவரது துஆ ஏற்கப்படும். அவர் உறுதியுடன் உளூச் செய்து தொழுதால், அவரது தொழுகையும் அங்கீகரிக்கப்படும்.) புகாரி மற்றும் ஸுனன் நூலாசிரியர்களும் இந்த ஹதீஸைப் பதிவு செய்துள்ளனர். இப்னு அபீ நஜீஹ் அவர்கள் வழியாக முஜாஹித் அவர்கள் இந்த ஆயத்திற்கு விளக்கமளிக்கும்போது,\n\r\n\n\r\nوَسَبِّحْ بِحَمْدِ رَبِّكَ حِينَ تَقُومُ\n\r\n\n\r\n(நீர் எழும்போது உமது இறைவனின் புகழைக் கொண்டு அவனைத் துதிப்பீராக.) என்று கூறிவிட்டு, \"நீர் அமர்ந்திருக்கும் ஒவ்வொரு சபையிலிருந்து எழும்போதும்\" என்று கூறினார்கள். அத்-தவ்ரீ அவர்கள், அபூ இஸ்ஹாக் வழியாக அபூ அஹ்வஸ் அவர்கள் கூறியதாகக் குறிப்பிடுகிறார்கள்:\n\r\n\n\r\nوَسَبِّحْ بِحَمْدِ رَبِّكَ حِينَ تَقُومُ\n\r\n\n\r\n(நீர் எழும்போது உமது இறைவனின் புகழைக் கொண்டு அவனைத் துதிப்பீராக.) \"ஒருவர் ஒரு சபையிலிருந்து எழும்போது, 'யா அல்லாஹ்! நீ தூய்மையானவன், உன்னைப் புகழ்கிறேன்' என்று கூற வேண்டும்.\" அபூ ஹுரைரா (ரழி) அவர்கள், நபி (ஸல்) அவர்கள் பின்வருமாறு கூறினார்கள் என்று அறிவிக்கிறார்கள்:\n\r\n\n\r\n«مَنْ جَلَسَ فِي مَجْلِسٍ فَكَثُرَ فِيهِ لَغَطُهُ، فَقَالَ قَبْلَ أَنْ يَقُومَ مِنْ مَجْلِسِهِ: سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ، إِلَّا غَفَرَ اللهُ لَهُ مَا كَانَ فِي مَجْلِسِهِ ذلِك»\n\r\n\n\r\n(யார் ஒரு சபையில் அமர்ந்து, அதில் வீணான பேச்சுகளை அதிகமாகப் பேசிவிட்டு, அந்தச் சபையிலிருந்து எழுவதற்கு முன்பாக, 'ஸுப்ஹானகல்லாஹும்ம வபிஹம்திக, அஷ்ஹது அன் லா இலாஹ இல்லா அன்த, அஸ்தஃபிருக வஅதூபு இலைக்' என்று கூறுகிறாரோ, அந்தச் சபையில் அவர் பேசிய வீணான பேச்சுகளை அல்லாஹ் மன்னித்துவிடுவான்.) இதனை திர்மிதீ அவர்கள் பதிவு செய்துள்ளார்கள், இது அவருடைய வாசகமாகும். மேலும் நஸயீ அவர்கள் 'அமல் அல்-யவ்ம் வல்-லைலா' என்ற நூலிலும் இதைப் பதிவு செய்துள்ளார்கள். திர்மிதீ அவர்கள் இது \"ஹஸன் ஸஹீஹ்\" என்று கூறியுள்ளார். இமாம் ஹாகிம் அவர்களும் தனது முஸ்தத்ரக் நூலில் இதைப் பதிவு செய்து, \"இதன் அறிவிப்பாளர் தொடர் முஸ்லிமின் நிபந்தனைகளுக்கு உட்பட்டது\" என்று குறிப்பிட்டுள்ளார். மேலான அல்லாஹ் கூறினான்;\n\r\n\n\r\nوَمِنَ الَّيْلِ فَسَبِّحْهُ\n\r\n\n\r\n(மேலும் இரவிலும் அவனைத் துதிப்பீராக), அதாவது குர்ஆன் ஓதுவதன் மூலமும், இரவுத் தொழுகை மூலமும் அல்லாஹ்வை நினைவு கூர்ந்து வணங்குங்கள். மேலான அல்லாஹ் மற்றொரு ஆயத்தில் கூறினான்,\n\r\n\n\r\nوَمِنَ الَّيْلِ فَتَهَجَّدْ بِهِ نَافِلَةً لَّكَ عَسَى أَن يَبْعَثَكَ رَبُّكَ مَقَاماً مَّحْمُودًا\n\r\n\n\r\n(மேலும் இரவின் ஒரு பகுதியில் தஹஜ்ஜுத் தொழுவீராக! இது உமக்கு உபரியான வணக்கமாகும். இதன் மூலம் உமது இறைவன் உம்மை மகாமன் மஹ்மூத் (புகழத்தக்க இடம்) எனும் நிலையில் எழுப்பக்கூடும்.) (17:79) அல்லாஹ் கூறினான்;\n\r\n\n\r\nوَإِدْبَارَ النُّجُومِ\n\r\n\n\r\n(நட்சத்திரங்கள் மறையும் நேரத்திலும்.) இப்னு அப்பாஸ் (ரழி) அவர்களின் அறிவிப்பின்படி, இது ஃபஜ்ர் தொழுகைக்கு முன்னால் தொழப்படும் இரண்டு ரக்அத் சுன்னத் தொழுகையைக் குறிக்கும். இந்த இரண்டு ரக்அத்களும் நட்சத்திரங்கள் மறையத் தொடங்கும் முன் செய்யப்படும் ஒரு உறுதிப்படுத்தப்பட்ட ஸுன்னத் ஆகும். ஆயிஷா (ரழி) அவர்கள் கூறியதாக 'ஸஹீஹைன்' நூல்களில் இவ்வாறு இடம்பெற்றுள்ளது: \"நபி (ஸல்) அவர்கள் ஃபஜ்ருடைய இரண்டு (ஸுன்னத்) ரக்அத்களைப் போல வேறெந்த உபரியான தொழுகையையும் இவ்வளவு பேணுதலாகத் தொழுததில்லை.\" முஸ்லிமில் இடம்பெற்றுள்ள மற்றோர் அறிவிப்பில் நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«رَكْعَتَا الْفَجْرِ خَيْرٌ مِنَ الدُّنْيَا وَمَا فِيهَا»\n\r\n\n\r\n(ஃபஜ்ருடைய இரண்டு (ஸுன்னத்) ரக்அத்கள் இவ்வுலகையும் அதிலுள்ள அனைத்தையும் விடச் சிறந்ததாகும்.)\n\r\n\n\r\nஇத்துடன் ஸூரதுத் தூரின் தஃப்ஸீர் நிறைவுற்றது. எல்லாப் புகழும் நன்றியும் அல்லாஹ்வுக்கே உரியது."}}};})(self);
